export const MIGRATIONS: Array<{ name: string; sql: string }> = [
  { name: "0000_core.sql", sql: "-- Meridian core schema (PostgreSQL / AlloyDB).\n-- Sharding model: every tenant-owned row carries shard_id = abs(hashtext(customer_id)) % 1024.\n-- Logical shards map to physical AlloyDB clusters via the shard_map table (router lives in app layer).\n-- High-cardinality tables (services, order_lines, usage) are additionally HASH partitioned so a\n-- single IoT enterprise with millions of devices does not create an unbounded hot partition.\n\nCREATE EXTENSION IF NOT EXISTS ltree;\n\nCREATE TABLE shard_map (\n  logical_shard smallint PRIMARY KEY CHECK (logical_shard BETWEEN 0 AND 1023),\n  cluster_name  text NOT NULL,\n  read_only     boolean NOT NULL DEFAULT false\n);\n\nCREATE TYPE customer_segment AS ENUM ('CONSUMER','FAMILY','ENTERPRISE','IOT_ENTERPRISE');\nCREATE TYPE account_status   AS ENUM ('ACTIVE','SUSPENDED','CLOSED');\nCREATE TYPE service_type     AS ENUM ('MOBILE','FIBER','IOT','SUBSCRIPTION');\nCREATE TYPE service_status   AS ENUM ('PENDING','ACTIVE','SUSPENDED','PORTING_OUT','TERMINATED');\nCREATE TYPE membership_role  AS ENUM ('OWNER','MEMBER','DEPARTMENT');\n\n-- ───────────── Customer hierarchy ─────────────\nCREATE TABLE customers (\n  id                uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id          smallint NOT NULL,\n  segment           customer_segment NOT NULL,\n  display_name      text NOT NULL,\n  id_document_ref   text NOT NULL,           -- encrypted at rest (envelope encryption, KMS)\n  market_code       char(2) NOT NULL,\n  parent_customer_id uuid,\n  hierarchy_path    ltree NOT NULL,          -- enterprise -> department -> sub-department\n  version           integer NOT NULL DEFAULT 1,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (shard_id, id)\n) PARTITION BY LIST (shard_id);\nCREATE INDEX customers_path_gist ON customers USING gist (hierarchy_path);\n\nCREATE TABLE accounts (\n  id              uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id        smallint NOT NULL,\n  customer_id     uuid NOT NULL,\n  bill_cycle_day  smallint CHECK (bill_cycle_day IS NULL OR bill_cycle_day BETWEEN 1 AND 28), -- NULL = daily\n  status          account_status NOT NULL DEFAULT 'ACTIVE',\n  currency        char(3) NOT NULL,\n  payer_account_id uuid,\n  version         integer NOT NULL DEFAULT 1,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  updated_at      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (shard_id, id)\n) PARTITION BY LIST (shard_id);\nCREATE INDEX accounts_customer_idx ON accounts (shard_id, customer_id);\nCREATE INDEX accounts_cycle_idx ON accounts (bill_cycle_day) WHERE status = 'ACTIVE';\n\nCREATE TABLE services (\n  id                   uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id             smallint NOT NULL,\n  account_id           uuid NOT NULL,\n  customer_id          uuid NOT NULL,\n  type                 service_type NOT NULL,\n  identifier           text NOT NULL,        -- MSISDN / circuit id / IoT device id\n  iccid                text,\n  offer_id             text NOT NULL,\n  status               service_status NOT NULL DEFAULT 'PENDING',\n  contract_start       timestamptz,\n  contract_term_months smallint,\n  version              integer NOT NULL DEFAULT 1,\n  created_at           timestamptz NOT NULL DEFAULT now(),\n  updated_at           timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (shard_id, identifier, id)   -- unique/PK on a partitioned table must include the partition key\n) PARTITION BY HASH (identifier);          -- spreads multi-million-device IoT fleets; MSISDN lookups hit 1 partition\nCREATE UNIQUE INDEX services_identifier_uq ON services (shard_id, type, identifier);\nCREATE INDEX services_account_idx ON services (shard_id, account_id);\n\nCREATE TABLE group_memberships (\n  group_customer_id  uuid NOT NULL,\n  member_customer_id uuid NOT NULL,\n  shard_id           smallint NOT NULL,\n  role               membership_role NOT NULL,\n  PRIMARY KEY (shard_id, group_customer_id, member_customer_id)\n);\n\n-- ───────────── Order management ─────────────\nCREATE TYPE order_channel AS ENUM ('SELF_SERVE','RETAIL_ASSISTED','QUICK_SALE','TELESALES','DEALER','CALL_CENTER');\nCREATE TYPE order_state AS ENUM ('DRAFT','SUBMITTED','VALIDATED','PAYMENT_PENDING','PAID','FULFILMENT',\n  'AWAITING_INSTALLATION','SHIPPED','DELIVERED','ACTIVATED','COMPLETED','CANCELLED','FAILED');\nCREATE TYPE payment_method AS ENUM ('CREDIT_CARD','CASH','QR','INSTALLMENT','ETC_CHARGE');\nCREATE TYPE payment_status AS ENUM ('PENDING','AUTHORISED','CAPTURED','FAILED','REFUNDED');\n\nCREATE TABLE orders (\n  id                    uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id              smallint NOT NULL,\n  customer_id           uuid NOT NULL,\n  channel               order_channel NOT NULL,\n  state                 order_state NOT NULL DEFAULT 'DRAFT',\n  total_minor           bigint NOT NULL,\n  currency              char(3) NOT NULL,\n  store_id              text,\n  salesperson_id        text,\n  dealer_id             text,\n  commission_eligible   boolean NOT NULL DEFAULT false,\n  workflow_id           text,\n  point_of_no_return_at timestamptz,\n  version               integer NOT NULL DEFAULT 1,\n  created_at            timestamptz NOT NULL DEFAULT now(),\n  updated_at            timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (shard_id, id)\n) PARTITION BY LIST (shard_id);\nCREATE INDEX orders_customer_idx ON orders (shard_id, customer_id, created_at DESC);\nCREATE INDEX orders_state_idx ON orders (state) WHERE state NOT IN ('COMPLETED','CANCELLED','FAILED');\n\nCREATE TABLE order_lines (\n  id            uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id      smallint NOT NULL,\n  order_id      uuid NOT NULL,\n  offer_id      text NOT NULL,\n  quantity      integer NOT NULL CHECK (quantity > 0),\n  unit_price_minor bigint NOT NULL,\n  msisdn        text,\n  serial_number text,\n  PRIMARY KEY (shard_id, order_id, id)\n) PARTITION BY HASH (order_id);\nCREATE INDEX order_lines_order_idx ON order_lines (shard_id, order_id);\n\n-- Append-only audit of state transitions (also published to Kafka topic meridian.order.events).\nCREATE TABLE order_state_history (\n  id          bigint GENERATED ALWAYS AS IDENTITY,\n  shard_id    smallint NOT NULL,\n  order_id    uuid NOT NULL,\n  from_state  order_state,\n  to_state    order_state NOT NULL,\n  actor       text NOT NULL,\n  reason      text,\n  occurred_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (shard_id, id)\n);\n\nCREATE TABLE payments (\n  id             uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id       smallint NOT NULL,\n  order_id       uuid NOT NULL,\n  method         payment_method NOT NULL,\n  status         payment_status NOT NULL DEFAULT 'PENDING',\n  amount_minor   bigint NOT NULL,\n  currency       char(3) NOT NULL,\n  installment_months smallint,\n  gateway_ref    text,\n  idempotency_key text NOT NULL,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (shard_id, id),\n  UNIQUE (shard_id, idempotency_key)\n);\n\nCREATE TABLE installation_appointments (\n  id          uuid NOT NULL DEFAULT gen_random_uuid(),\n  shard_id    smallint NOT NULL,\n  order_id    uuid NOT NULL,\n  slot_start  timestamptz NOT NULL,\n  slot_end    timestamptz NOT NULL,\n  technician_id text,\n  status      text NOT NULL DEFAULT 'BOOKED' CHECK (status IN ('BOOKED','DISPATCHED','DONE','CANCELLED')),\n  PRIMARY KEY (shard_id, id)\n);\n\nCREATE TABLE inventory_stock (\n  location_id text NOT NULL,           -- store, dealer or warehouse\n  sku         text NOT NULL,\n  on_hand     integer NOT NULL CHECK (on_hand >= 0),\n  reserved    integer NOT NULL DEFAULT 0 CHECK (reserved >= 0 AND reserved <= on_hand),\n  PRIMARY KEY (location_id, sku)\n);\n\nCREATE TABLE inventory_reservations (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id    uuid NOT NULL,\n  location_id text NOT NULL,\n  sku         text NOT NULL,\n  quantity    integer NOT NULL CHECK (quantity > 0),\n  released_at timestamptz,\n  FOREIGN KEY (location_id, sku) REFERENCES inventory_stock (location_id, sku)\n);\n" },
  { name: "0001_create_shard_partitions.sql", sql: "-- Creates logical-shard list partitions and hash sub-partitions for the dev cluster.\n-- Production runs this per physical cluster for only the shards that cluster owns (see shard_map).\nDO $$\nDECLARE s int; t text; r int;\nBEGIN\n  FOR s IN 0..15 LOOP   -- dev: 16 of 1024 shards\n    FOREACH t IN ARRAY ARRAY['customers','accounts','orders'] LOOP\n      EXECUTE format('CREATE TABLE %I PARTITION OF %I FOR VALUES IN (%s)', t || '_s' || s, t, s);\n    END LOOP;\n  END LOOP;\n  FOR r IN 0..7 LOOP\n    EXECUTE format('CREATE TABLE services_h%s PARTITION OF services FOR VALUES WITH (MODULUS 8, REMAINDER %s)', r, r);\n    EXECUTE format('CREATE TABLE order_lines_h%s PARTITION OF order_lines FOR VALUES WITH (MODULUS 8, REMAINDER %s)', r, r);\n  END LOOP;\nEND $$;\n" },
  { name: "0002_bss_core.sql", sql: "-- BSS core additions: catalog, billing, ledger, cases, commissions, lifecycle columns.\n-- Money is integer minor units. Dates that are business dates (invoice periods, due dates) are `date`.\n\n-- ───────── Customer / account / service additions ─────────\nALTER TABLE customers ADD COLUMN email text, ADD COLUMN phone text,\n  ADD COLUMN status text NOT NULL DEFAULT 'ACTIVE',\n  ADD COLUMN id_document_hash text;               -- HMAC of the ID document for duplicate detection\nALTER TABLE accounts  ADD COLUMN name text NOT NULL DEFAULT 'Main account',\n  ADD COLUMN dunning_stage smallint NOT NULL DEFAULT 0;\nALTER TABLE services  ADD COLUMN activated_at timestamptz, ADD COLUMN terminated_at timestamptz,\n  ADD COLUMN order_id uuid, ADD COLUMN suspended_reason text;\nCREATE INDEX services_offer_idx ON services (offer_id);\nCREATE INDEX services_status_idx ON services (status);\nCREATE INDEX customers_name_idx ON customers (lower(display_name));\nCREATE INDEX customers_phone_idx ON customers (phone);\n\nCREATE SEQUENCE msisdn_seq START 91000000;       -- local number part, prefixed with the market dial code\nCREATE SEQUENCE circuit_seq START 100000;\nCREATE SEQUENCE invoice_seq START 1;\n\n-- Recurring / instalment / one-off charges attached to a service, consumed by the bill run.\nCREATE TABLE service_charges (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  shard_id         smallint NOT NULL,\n  service_id       uuid NOT NULL,\n  account_id       uuid NOT NULL,\n  kind             text NOT NULL CHECK (kind IN ('INSTALLMENT','ADJUSTMENT')),\n  description      text NOT NULL,\n  amount_minor     bigint NOT NULL,\n  tax_inclusive    boolean NOT NULL DEFAULT true,\n  remaining_cycles integer NOT NULL CHECK (remaining_cycles >= 0),\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX service_charges_account_idx ON service_charges (account_id) WHERE remaining_cycles > 0;\n\n-- ───────── Product catalog (Postgres/JSONB implementation; the Mongo service mirrors this model) ─────────\nCREATE TABLE catalog_nodes (\n  id          text PRIMARY KEY,\n  level       text NOT NULL CHECK (level IN ('NETWORK_TYPE','CATEGORY','GROUP','OFFER')),\n  code        text NOT NULL,\n  name        text NOT NULL,\n  path        text NOT NULL UNIQUE,\n  parent_id   text REFERENCES catalog_nodes(id),\n  status      text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','RETIRED')),\n  kind        text,\n  markets     text[] NOT NULL DEFAULT '{}',\n  data        jsonb NOT NULL DEFAULT '{}',        -- prices, contract, fulfilment, characteristics, requires/excludes\n  version     integer NOT NULL DEFAULT 1,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX catalog_nodes_parent_idx ON catalog_nodes (parent_id);\nCREATE INDEX catalog_nodes_kind_idx ON catalog_nodes (level, kind, status);\n\n-- ───────── Orders ─────────\nALTER TABLE orders ADD COLUMN account_id uuid, ADD COLUMN market_code char(2) NOT NULL DEFAULT 'SG',\n  ADD COLUMN payment_method payment_method, ADD COLUMN installment_months smallint,\n  ADD COLUMN pending_tasks text[] NOT NULL DEFAULT '{}',   -- INSTALL | SHIP | PICKUP outstanding before activation\n  ADD COLUMN fulfilment jsonb NOT NULL DEFAULT '{}',        -- slot, tracking number, delivery address\n  ADD COLUMN failure_reason text, ADD COLUMN completed_at timestamptz;\nALTER TABLE order_lines ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN net_minor bigint NOT NULL DEFAULT 0,\n  ADD COLUMN tax_minor bigint NOT NULL DEFAULT 0;\nALTER TABLE payments ALTER COLUMN order_id DROP NOT NULL, ADD COLUMN invoice_id uuid, ADD COLUMN reference text;\nALTER TABLE payments ADD CONSTRAINT payments_target CHECK (order_id IS NOT NULL OR invoice_id IS NOT NULL);\nALTER TABLE inventory_reservations ADD COLUMN consumed_at timestamptz;\n\nCREATE TABLE commissions (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id       uuid NOT NULL,\n  store_id       text, salesperson_id text, dealer_id text,\n  basis_minor    bigint NOT NULL,\n  rate_bps       integer NOT NULL,\n  amount_minor   bigint NOT NULL,\n  currency       char(3) NOT NULL,\n  status         text NOT NULL DEFAULT 'ACCRUED' CHECK (status IN ('ACCRUED','PAID','CLAWED_BACK')),\n  created_at     timestamptz NOT NULL DEFAULT now()\n);\n\n-- ───────── Billing ─────────\nCREATE TABLE invoices (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  shard_id      smallint NOT NULL,\n  number        text NOT NULL UNIQUE,\n  account_id    uuid NOT NULL,\n  customer_id   uuid NOT NULL,\n  kind          text NOT NULL DEFAULT 'CYCLE' CHECK (kind IN ('CYCLE','FINAL','ADJUSTMENT')),\n  period_start  date NOT NULL,\n  period_end    date NOT NULL,                   -- inclusive\n  issue_date    date NOT NULL,\n  due_date      date NOT NULL,\n  status        text NOT NULL DEFAULT 'ISSUED' CHECK (status IN ('ISSUED','OVERDUE','PAID','VOID')),\n  currency      char(3) NOT NULL,\n  net_minor     bigint NOT NULL,\n  tax_minor     bigint NOT NULL,\n  total_minor   bigint NOT NULL,\n  paid_minor    bigint NOT NULL DEFAULT 0,\n  credited_minor bigint NOT NULL DEFAULT 0,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  CHECK (total_minor = net_minor + tax_minor)\n);\n-- One cycle invoice per account per period: makes bill runs idempotent and safe to retry.\nCREATE UNIQUE INDEX invoices_cycle_uq ON invoices (account_id, period_start, period_end) WHERE kind = 'CYCLE';\nCREATE INDEX invoices_customer_idx ON invoices (customer_id, issue_date DESC);\nCREATE INDEX invoices_open_idx ON invoices (due_date) WHERE status IN ('ISSUED','OVERDUE');\n\nCREATE TABLE invoice_lines (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  invoice_id  uuid NOT NULL REFERENCES invoices(id),\n  service_id  uuid,\n  kind        text NOT NULL CHECK (kind IN ('RECURRING','INSTALLMENT','ETC','ADJUSTMENT')),\n  revenue_account text NOT NULL,                 -- GL account credited\n  description text NOT NULL,\n  net_minor   bigint NOT NULL,\n  tax_minor   bigint NOT NULL\n);\nCREATE INDEX invoice_lines_invoice_idx ON invoice_lines (invoice_id);\n\nALTER TABLE payments ADD CONSTRAINT payments_invoice_fk FOREIGN KEY (invoice_id) REFERENCES invoices(id);\n\n-- ───────── General ledger ─────────\nCREATE TABLE gl_batches (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  entry_count integer NOT NULL,\n  debit_minor bigint NOT NULL,\n  credit_minor bigint NOT NULL\n);\nCREATE TABLE gl_entries (\n  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  journal_id    uuid NOT NULL,                   -- all lines of one business event share a journal and must balance\n  entry_date    date NOT NULL,\n  source_type   text NOT NULL,                   -- ORDER | INVOICE | PAYMENT | CREDIT_NOTE | REFUND\n  source_id     text NOT NULL,\n  account_code  text NOT NULL,\n  description   text NOT NULL,\n  debit_minor   bigint NOT NULL DEFAULT 0 CHECK (debit_minor >= 0),\n  credit_minor  bigint NOT NULL DEFAULT 0 CHECK (credit_minor >= 0),\n  currency      char(3) NOT NULL,\n  exported_batch_id uuid REFERENCES gl_batches(id),\n  CHECK ((debit_minor = 0) <> (credit_minor = 0))\n);\nCREATE INDEX gl_entries_unexported_idx ON gl_entries (entry_date) WHERE exported_batch_id IS NULL;\nCREATE INDEX gl_entries_source_idx ON gl_entries (source_type, source_id);\n\n-- ───────── Cases (Customer 360) ─────────\nCREATE TABLE cases (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  number       text NOT NULL UNIQUE,\n  customer_id  uuid NOT NULL,\n  service_id   uuid,\n  type         text NOT NULL CHECK (type IN ('FIBER_ASSURANCE','BILLING_REFUND','MNP_PORT_OUT','GENERAL')),\n  status       text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','IN_PROGRESS','RESOLVED','CLOSED')),\n  priority     text NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('LOW','NORMAL','HIGH','URGENT')),\n  subject      text NOT NULL,\n  notes        jsonb NOT NULL DEFAULT '[]',\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  updated_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE SEQUENCE case_seq START 1;\nCREATE INDEX cases_customer_idx ON cases (customer_id, created_at DESC);\nCREATE INDEX cases_open_idx ON cases (status) WHERE status IN ('OPEN','IN_PROGRESS');\n\n-- ───────── Audit trail ─────────\nCREATE TABLE audit_log (\n  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  at         timestamptz NOT NULL DEFAULT now(),\n  actor      text NOT NULL,\n  entity     text NOT NULL,\n  entity_id  text NOT NULL,\n  action     text NOT NULL,\n  detail     jsonb NOT NULL DEFAULT '{}'\n);\nCREATE INDEX audit_log_entity_idx ON audit_log (entity, entity_id, at DESC);\n\n-- ───────── Global identifier registry ─────────\n-- services is sharded, so its unique index only guarantees uniqueness *within a shard*. MSISDNs, circuit ids and\n-- IoT ids must be unique platform-wide, so they are claimed here (unsharded, single-writer-per-key) in the same\n-- transaction that creates the service. Released numbers stay registered (quarantine) until a recycling job removes them.\nCREATE TABLE identifier_registry (\n  type        text NOT NULL,\n  identifier  text NOT NULL,\n  service_id  uuid NOT NULL,\n  claimed_at  timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (type, identifier)\n);\n" },
  { name: "0003_auth.sql", sql: "-- Identity, sessions and request hardening.\n\nCREATE TABLE users (\n  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  username             text NOT NULL,\n  display_name         text NOT NULL,\n  email                text,\n  password_hash        text,                       -- scrypt; NULL for the environment-defined super user (never DB-authenticated)\n  roles                text[] NOT NULL DEFAULT '{}',\n  is_superuser         boolean NOT NULL DEFAULT false,\n  status               text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')),\n  must_change_password boolean NOT NULL DEFAULT false,\n  failed_attempts      integer NOT NULL DEFAULT 0,\n  locked_until         timestamptz,\n  last_login_at        timestamptz,\n  password_changed_at  timestamptz,\n  -- Data scope: a store/dealer user only sees their own orders; a portal user is bound to one customer.\n  store_id             text,\n  dealer_id            text,\n  customer_id          uuid,\n  market_code          char(2) NOT NULL DEFAULT 'SG',\n  created_by           text NOT NULL DEFAULT 'system',\n  created_at           timestamptz NOT NULL DEFAULT now(),\n  updated_at           timestamptz NOT NULL DEFAULT now(),\n  CHECK (is_superuser OR password_hash IS NOT NULL)\n);\nCREATE UNIQUE INDEX users_username_uq ON users (lower(username));\nCREATE UNIQUE INDEX users_customer_uq ON users (customer_id) WHERE customer_id IS NOT NULL;\n\n-- Opaque server-side sessions: only a SHA-256 of the cookie token is stored, so a database leak cannot be replayed.\nCREATE TABLE sessions (\n  id           text PRIMARY KEY,\n  user_id      uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  auth_epoch   text NOT NULL DEFAULT '',          -- super-user sessions die when the environment credentials rotate\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  last_seen_at timestamptz NOT NULL DEFAULT now(),\n  expires_at   timestamptz NOT NULL,              -- absolute lifetime\n  revoked_at   timestamptz,\n  ip           text,\n  user_agent   text\n);\nCREATE INDEX sessions_user_idx ON sessions (user_id) WHERE revoked_at IS NULL;\n\n-- Failed-login ledger used for throttling by client address and by (possibly non-existent) username.\nCREATE TABLE auth_attempts (\n  id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  key    text NOT NULL,                           -- 'ip:<addr>' or 'user:<lowercased name>'\n  at     timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX auth_attempts_key_idx ON auth_attempts (key, at DESC);\n\n-- Makes \"place order\" safe to retry (double-click, flaky network).\nCREATE TABLE idempotency_keys (\n  key        text NOT NULL,\n  user_id    uuid NOT NULL,\n  order_id   uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (user_id, key)\n);\n\nALTER TABLE orders ADD COLUMN created_by text;\n" },
  { name: "0004_catalog_settings.sql", sql: "-- Catalog editing (ordering) and operator settings (regional format, appearance, logo).\n\nALTER TABLE catalog_nodes ADD COLUMN sort_order integer NOT NULL DEFAULT 0;\nCREATE INDEX catalog_nodes_sort_idx ON catalog_nodes (parent_id, sort_order, name);\n\n-- Key/value settings, written only by the super user ('regional', 'branding').\nCREATE TABLE settings (\n  key         text PRIMARY KEY,\n  value       jsonb NOT NULL,\n  updated_by  text NOT NULL,\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\n\n-- Small binary assets (the portal logo). Stored in the database so the app needs no writable filesystem.\nCREATE TABLE assets (\n  name         text PRIMARY KEY,\n  content_type text NOT NULL,\n  bytes        bytea NOT NULL,\n  sha256       text NOT NULL,\n  width        integer,\n  height       integer,\n  updated_by   text NOT NULL,\n  updated_at   timestamptz NOT NULL DEFAULT now()\n);\n" },
  { name: "0005_store_kyc.sql", sql: "-- Store-front, KYC and payment gateways.\n--  * api_clients: machine credentials for an externally hosted store-front (only a hash of the key is kept)\n--  * applications: a sign-up / purchase in progress, before it becomes a customer and an order\n--  * kyc_cases + kyc_documents: identity verification evidence (ID number and images are encrypted by the application)\n--  * payment_intents + webhook_events: what a payment gateway was asked to collect, and which gateway events were already processed\n\nALTER TABLE customers\n  ADD COLUMN kyc_status text NOT NULL DEFAULT 'NOT_VERIFIED' CHECK (kyc_status IN ('NOT_VERIFIED','VERIFIED')),\n  ADD COLUMN kyc_verified_at timestamptz;\n\nCREATE TABLE api_clients (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name         text NOT NULL,\n  key_prefix   text NOT NULL UNIQUE,         -- public part of the key, used to find the row\n  key_hash     text NOT NULL,                -- sha256 of the secret part\n  scopes       text[] NOT NULL DEFAULT '{store}',\n  status       text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','REVOKED')),\n  created_by   text NOT NULL,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  last_used_at timestamptz,\n  revoked_at   timestamptz\n);\n\nCREATE TABLE applications (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id   uuid REFERENCES api_clients(id),   -- set for the external store-front\n  channel     text NOT NULL CHECK (channel IN ('SELF_SERVE','RETAIL_ASSISTED')),\n  status      text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','KYC_REVIEW','KYC_APPROVED','KYC_REJECTED','ORDERED','CANCELLED','EXPIRED')),\n  token_hash  text,                              -- self-serve: the shopper's resume token (hash)\n  customer_id uuid,                              -- existing customer (assisted) or the one created at checkout\n  order_id    uuid,\n  lines       jsonb NOT NULL DEFAULT '[]',\n  personal    jsonb NOT NULL DEFAULT '{}',\n  address     jsonb,\n  consent     jsonb,\n  store_id    text,\n  created_by  text,                              -- staff username for assisted sales\n  created_ip  text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now(),\n  expires_at  timestamptz NOT NULL\n);\nCREATE INDEX applications_status_idx ON applications (status, created_at DESC);\nCREATE INDEX applications_store_idx ON applications (store_id, created_at DESC);\n\nCREATE TABLE kyc_cases (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  application_id   uuid NOT NULL UNIQUE REFERENCES applications(id),\n  customer_id      uuid,\n  method           text NOT NULL CHECK (method IN ('DOCUMENT_REMOTE','IN_PERSON')),\n  status           text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED')),\n  full_name        text NOT NULL,\n  date_of_birth    date NOT NULL,\n  nationality      text,\n  id_type          text NOT NULL,\n  id_number_enc    text NOT NULL,                -- AES-256-GCM\n  id_number_hash   text NOT NULL,                -- keyed hash, for duplicate detection\n  id_number_masked text NOT NULL,\n  id_expiry        date,\n  flags            text[] NOT NULL DEFAULT '{}', -- e.g. DUPLICATE_IDENTITY, NAME_MISMATCH\n  checks           jsonb NOT NULL DEFAULT '{}',\n  attestation      jsonb,                        -- in-person: who sighted the original document\n  decided_by       text,\n  decided_at       timestamptz,\n  decision_reason  text,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX kyc_cases_status_idx ON kyc_cases (status, created_at);\n\nCREATE TABLE kyc_documents (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  case_id      uuid NOT NULL REFERENCES kyc_cases(id) ON DELETE CASCADE,\n  application_id uuid NOT NULL REFERENCES applications(id),\n  kind         text NOT NULL CHECK (kind IN ('ID_FRONT','ID_BACK','SELFIE','PROOF_OF_ADDRESS','SIGNATURE')),\n  content_type text NOT NULL,\n  size_bytes   integer NOT NULL,\n  sha256       text NOT NULL,                    -- of the plain bytes\n  data         bytea NOT NULL,                   -- AES-256-GCM (iv | tag | ciphertext)\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX kyc_documents_app_idx ON kyc_documents (application_id, kind);\n\nCREATE TABLE payment_intents (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  application_id uuid REFERENCES applications(id),\n  order_id       uuid NOT NULL,\n  gateway        text NOT NULL,\n  gateway_ref    text NOT NULL,\n  amount_minor   bigint NOT NULL,\n  currency       char(3) NOT NULL,\n  status         text NOT NULL DEFAULT 'REQUIRES_PAYMENT' CHECK (status IN ('REQUIRES_PAYMENT','SUCCEEDED','FAILED','CANCELLED')),\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  updated_at     timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (gateway, gateway_ref)\n);\nCREATE INDEX payment_intents_order_idx ON payment_intents (order_id);\n\nCREATE TABLE webhook_events (\n  gateway     text NOT NULL,\n  event_id    text NOT NULL,\n  received_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (gateway, event_id)\n);\n" },
  { name: "0006_repair_catalog_paths.sql", sql: "-- Catalog paths must be built from node ids (parent path + '/' + id). Catalogs seeded by earlier releases stored codes for some levels\n-- (e.g. 'mobile/postpaid/device/...' under a group whose id is 'grp-device'), which hid those offers from path-based checks such as the store-front.\n-- Rebuild every path from the parent chain; already-correct rows are untouched.\nWITH RECURSIVE t AS (\n  SELECT id, id::text AS np FROM catalog_nodes WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.id, t.np || '/' || c.id FROM catalog_nodes c JOIN t ON c.parent_id = t.id\n)\nUPDATE catalog_nodes n SET path = t.np FROM t WHERE n.id = t.id AND n.path <> t.np;\n" },
  { name: "0007_offer_line_items.sql", sql: "-- A fifth catalog level: offer line items (the components an offer includes: data allowance, calls, device, SIM…).\n-- They live in catalog_nodes under their offer (level LINE_ITEM, parent_id = the offer); their attributes are in `data`.\nALTER TABLE catalog_nodes DROP CONSTRAINT catalog_nodes_level_check;\nALTER TABLE catalog_nodes ADD CONSTRAINT catalog_nodes_level_check CHECK (level IN ('NETWORK_TYPE','CATEGORY','GROUP','OFFER','LINE_ITEM'));\n" },
  { name: "0008_scale_indexes.sql", sql: "-- Indexes for lists and search on tables of millions of rows. Every list is ordered by an indexed key and continued with a keyset cursor;\n-- free-text search uses prefix btrees and a GIN full-text index, never `%term%`.\n\n-- customers: newest-first listing, word-prefix name search, e-mail / phone prefix lookup, hierarchy children\nCREATE INDEX IF NOT EXISTS customers_created_idx   ON customers (created_at DESC, id DESC);\nCREATE INDEX IF NOT EXISTS customers_fts_idx       ON customers USING gin (to_tsvector('simple', display_name));\nCREATE INDEX IF NOT EXISTS customers_email_pfx_idx ON customers (lower(email) text_pattern_ops);\nCREATE INDEX IF NOT EXISTS customers_phone_pfx_idx ON customers (phone text_pattern_ops);\nCREATE INDEX IF NOT EXISTS customers_parent_idx    ON customers (parent_customer_id, display_name, id) WHERE parent_customer_id IS NOT NULL;\n\n-- services: by customer, by number prefix, and the (identifier, id) keyset inside an account\nCREATE INDEX IF NOT EXISTS services_customer_idx   ON services (customer_id, status);\nCREATE INDEX IF NOT EXISTS services_ident_pfx_idx  ON services (identifier text_pattern_ops);\nCREATE INDEX IF NOT EXISTS services_acct_ident_idx ON services (account_id, identifier, id);\n\n-- orders\nCREATE INDEX IF NOT EXISTS orders_created_idx      ON orders (created_at DESC, id DESC);\nCREATE INDEX IF NOT EXISTS orders_store_idx        ON orders (store_id, created_at DESC) WHERE store_id IS NOT NULL;\nCREATE INDEX IF NOT EXISTS orders_dealer_idx       ON orders (dealer_id, created_at DESC) WHERE dealer_id IS NOT NULL;\nCREATE INDEX IF NOT EXISTS orders_channel_idx      ON orders (channel, created_at DESC);\n\n-- invoices\nCREATE INDEX IF NOT EXISTS invoices_issued_idx     ON invoices (issue_date DESC, number DESC);\nCREATE INDEX IF NOT EXISTS invoices_number_pfx_idx ON invoices (number text_pattern_ops);\nCREATE INDEX IF NOT EXISTS invoices_status_idx     ON invoices (status, issue_date DESC, number DESC);\nCREATE INDEX IF NOT EXISTS invoices_account_idx    ON invoices (account_id, issue_date DESC, number DESC);\n\n-- cases\nCREATE INDEX IF NOT EXISTS cases_created_idx       ON cases (created_at DESC, id DESC);\nCREATE INDEX IF NOT EXISTS cases_number_pfx_idx    ON cases (number text_pattern_ops);\nCREATE INDEX IF NOT EXISTS cases_status_idx        ON cases (status, created_at DESC, id DESC);\n\n-- stock, audit, users\nCREATE INDEX IF NOT EXISTS inventory_sku_pfx_idx   ON inventory_stock (sku text_pattern_ops);\nCREATE INDEX IF NOT EXISTS audit_actor_idx         ON audit_log (actor, id DESC);\nCREATE INDEX IF NOT EXISTS users_username_pfx_idx  ON users (lower(username) text_pattern_ops);\n\n-- catalog: name search and \"everything beneath this node\" (path prefix)\nCREATE INDEX IF NOT EXISTS catalog_nodes_fts_idx   ON catalog_nodes USING gin (to_tsvector('simple', name || ' ' || code));\nCREATE INDEX IF NOT EXISTS catalog_nodes_path_pfx_idx ON catalog_nodes (path text_pattern_ops);\nCREATE INDEX IF NOT EXISTS catalog_nodes_level_idx ON catalog_nodes (level, status, sort_order, name, id);\nCREATE INDEX IF NOT EXISTS order_lines_offer_idx   ON order_lines (offer_id);\n\n-- customer hierarchy navigation: accounts of a customer in creation order, memberships in both directions\nCREATE INDEX IF NOT EXISTS accounts_customer_created_idx ON accounts (customer_id, created_at, id);\nCREATE INDEX IF NOT EXISTS group_memberships_member_idx  ON group_memberships (member_customer_id);\nCREATE INDEX IF NOT EXISTS group_memberships_group_idx   ON group_memberships (group_customer_id, role);\n" },
  { name: "0009_order_groups.sql", sql: "-- Orders are fulfilled in independent parts (\"groups\"): service activation, goods delivery and installation. Each part has its own\n-- point of no return, so a shipped phone no longer locks a fibre line that has not started, and each part is cancelled and refunded on its own.\nCREATE TABLE order_groups (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id      uuid NOT NULL,\n  kind          text NOT NULL CHECK (kind IN ('ACTIVATION','GOODS','INSTALL')),\n  status        text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','LOCKED','DONE','CANCELLED','RETURNED')),\n  locked_at     timestamptz,                 -- point of no return reached: shipped / technician dispatched\n  done_at       timestamptz,                 -- delivered / installed / activated\n  cancelled_at  timestamptz,\n  due_at        timestamptz,                 -- service-level target (installation)\n  at_risk       boolean NOT NULL DEFAULT false,\n  refunded_minor bigint NOT NULL DEFAULT 0,\n  fee_minor     bigint NOT NULL DEFAULT 0,   -- retained on cancellation (late installation cancel, return deductions)\n  details       jsonb NOT NULL DEFAULT '{}', -- tracking number, appointment slot, cancel/return reason\n  UNIQUE (order_id, kind)\n);\nCREATE INDEX order_groups_open_idx ON order_groups (kind, status, due_at) WHERE status IN ('PENDING','LOCKED');\n\nALTER TABLE order_lines\n  ADD COLUMN fulfil_group text NOT NULL DEFAULT 'ACTIVATION' CHECK (fulfil_group IN ('ACTIVATION','GOODS','INSTALL')),\n  ADD COLUMN status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','CANCELLED','RETURNED')),\n  ADD COLUMN options jsonb NOT NULL DEFAULT '{}',            -- chosen device variant (colour, storage, sku)\n  ADD COLUMN pay_mode text NOT NULL DEFAULT 'UPFRONT' CHECK (pay_mode IN ('UPFRONT','INSTALLMENT')),\n  ADD COLUMN installment_months smallint,\n  ADD COLUMN down_payment_minor bigint NOT NULL DEFAULT 0,\n  ADD COLUMN paid_now_minor bigint NOT NULL DEFAULT 0,       -- what is taken at checkout for this line (upfront price or down payment)\n  ADD COLUMN discount_minor bigint NOT NULL DEFAULT 0,       -- bundle discount already included in net/tax\n  ADD COLUMN discount_rules text[] NOT NULL DEFAULT '{}';\n-- Existing orders: the whole upfront amount was paid at checkout, except instalment orders which paid nothing.\nUPDATE order_lines l SET paid_now_minor = CASE WHEN o.payment_method = 'INSTALLMENT' THEN 0 ELSE COALESCE(l.net_minor, 0) + COALESCE(l.tax_minor, 0) END,\n  pay_mode = CASE WHEN o.payment_method = 'INSTALLMENT' THEN 'INSTALLMENT' ELSE 'UPFRONT' END, installment_months = o.installment_months\n  FROM orders o WHERE o.id = l.order_id;\n\nALTER TABLE orders ADD COLUMN refunded_minor bigint NOT NULL DEFAULT 0;\nALTER TABLE payments ADD COLUMN refunded_minor bigint NOT NULL DEFAULT 0;\nUPDATE payments SET refunded_minor = amount_minor WHERE status = 'REFUNDED' AND amount_minor > 0;   -- earlier refunds were always whole\nALTER TABLE inventory_reservations ADD COLUMN fulfil_group text;   -- which part of the order the stock belongs to (null = whole order)\n\n-- Bundle discounts: \"fibre + a phone plan = 10% off the device\". Rules are data, edited by catalog managers.\nCREATE TABLE bundle_rules (\n  id         text PRIMARY KEY,\n  name       text NOT NULL,\n  status     text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT','ACTIVE','RETIRED')),\n  data       jsonb NOT NULL,                 -- { when: [\"kind:FIBER\",\"kind:SIM_DEVICE\"], target: \"kind:SIM_DEVICE\", percentBps | amountMinor }\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Per-offer device variants live in the offer's data (colour, storage, sku, price difference); nothing to migrate.\n\n-- Existing lines and in-flight orders join the new model.\nUPDATE order_lines l SET fulfil_group = CASE WHEN (c.data->'fulfilment'->>'requiresInstallation')::boolean THEN 'INSTALL'\n                                             WHEN (c.data->'fulfilment'->>'requiresShipping')::boolean THEN 'GOODS' ELSE 'ACTIVATION' END\n  FROM catalog_nodes c WHERE c.id = l.offer_id;\nUPDATE order_lines l SET status = 'CANCELLED' FROM orders o WHERE o.id = l.order_id AND o.state IN ('CANCELLED','FAILED');\nINSERT INTO order_groups (order_id, kind, status, locked_at)\n  SELECT o.id, 'GOODS', CASE WHEN o.point_of_no_return_at IS NOT NULL THEN 'LOCKED' ELSE 'PENDING' END, o.point_of_no_return_at\n    FROM orders o WHERE 'SHIP' = ANY(o.pending_tasks) AND o.state NOT IN ('COMPLETED','CANCELLED','FAILED');\nINSERT INTO order_groups (order_id, kind, status, locked_at, due_at)\n  SELECT o.id, 'INSTALL', CASE WHEN (o.fulfilment->>'dispatched')::boolean THEN 'LOCKED' ELSE 'PENDING' END, o.point_of_no_return_at, o.created_at + interval '14 days'\n    FROM orders o WHERE 'INSTALL' = ANY(o.pending_tasks) AND o.state NOT IN ('COMPLETED','CANCELLED','FAILED');\n\n-- Looking a customer up by ID document number (exact, through the keyed hash).\nCREATE INDEX IF NOT EXISTS customers_idhash_idx ON customers (id_document_hash) WHERE id_document_hash IS NOT NULL;\n" },
  { name: "0010_cancellation_rules.sql", sql: "-- Cancellation, return and escalation rules, edited in Settings → Cancellation. The standard policy is installed the first time it is needed.\nCREATE TABLE cancellation_rules (\n  id         text PRIMARY KEY,\n  name       text NOT NULL,\n  action     text NOT NULL CHECK (action IN ('CANCEL','RETURN','FLAG_AT_RISK','AUTO_CANCEL')),\n  group_kind text NOT NULL CHECK (group_kind IN ('GOODS','INSTALL','ACTIVATION','ANY')),\n  priority   integer NOT NULL,\n  enabled    boolean NOT NULL DEFAULT true,\n  data       jsonb NOT NULL,                       -- { when: [...], outcome: {...}, message, showInTerms }\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX cancellation_rules_order_idx ON cancellation_rules (action, priority, id);\n\n-- When a part of an order was opened, so \"days open\" rules and the sweep do not need the order row.\nALTER TABLE order_groups ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();\nUPDATE order_groups g SET created_at = o.created_at FROM orders o WHERE o.id = g.order_id;\n" },
  { name: "0011_dealers.sql", sql: "-- Dealers and their agents are master data kept in the CRM; CRM staff sell on their behalf and pick both on the order.\nCREATE TABLE dealers (\n  id           text PRIMARY KEY,                  -- the dealer id used on orders, users and commission\n  name         text NOT NULL,\n  status       text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  contact_name text,\n  email        text,\n  phone        text,\n  created_by   text,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  updated_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE TABLE dealer_agents (\n  id         text PRIMARY KEY,\n  dealer_id  text NOT NULL REFERENCES dealers(id),\n  name       text NOT NULL,\n  status     text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  email      text,\n  phone      text,\n  created_by text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX dealer_agents_dealer_idx ON dealer_agents (dealer_id, id);\nALTER TABLE orders ADD COLUMN dealer_agent_id text;\n\n-- Dealer ids that already exist on users and orders become dealers (named after their id until someone renames them).\nINSERT INTO dealers (id, name) SELECT DISTINCT d, d FROM (SELECT dealer_id AS d FROM users UNION SELECT dealer_id FROM orders) x WHERE d IS NOT NULL ON CONFLICT DO NOTHING;\n" },
  { name: "0012_segments_groups.sql", sql: "-- 1. Dealer ids are issued by the system (DLR-00001 …). Existing ids are kept; new ones continue after the highest numbered one.\nCREATE SEQUENCE dealer_id_seq;\nSELECT setval('dealer_id_seq', COALESCE((SELECT max(substr(id, 5)::int) FROM dealers WHERE id ~ '^DLR-[0-9]{1,9}$'), 0) + 1, false);\n\n-- 2. Customer segments are data the operator maintains (Settings → Customers), not a fixed list in the code.\nCREATE TABLE customer_segments (\n  id          text PRIMARY KEY,                    -- short code, issued from the name and never changed\n  name        text NOT NULL,\n  description text,\n  individual  boolean NOT NULL DEFAULT false,      -- true: one customer per ID document (a person); false: companies and fleets may share one\n  status      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  sort_order  integer NOT NULL DEFAULT 100,\n  created_by  text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX customer_segments_name_uq ON customer_segments (lower(name));\nINSERT INTO customer_segments (id, name, description, individual, sort_order) VALUES\n  ('CONSUMER',   'Consumer',   'Individuals buying for themselves or their household.', true,  10),\n  ('ENTERPRISE', 'Enterprise', 'Companies, with departments and many accounts.',        false, 20),\n  ('IOT',        'IoT',        'Connected-device fleets managed in bulk.',              false, 30);\n\n-- \"Family\" was a kind of customer; it is now a Group of services (below), so those customers become Consumers.\nALTER TABLE customers ALTER COLUMN segment TYPE text USING (CASE segment::text WHEN 'FAMILY' THEN 'CONSUMER' WHEN 'IOT_ENTERPRISE' THEN 'IOT' ELSE segment::text END);\nDROP TYPE customer_segment;\nALTER TABLE customers ADD CONSTRAINT customers_segment_fk FOREIGN KEY (segment) REFERENCES customer_segments (id);\n\n-- Every move between segments is kept, with who and why.\nCREATE TABLE customer_segment_changes (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  customer_id  uuid NOT NULL,\n  from_segment text NOT NULL,\n  to_segment   text NOT NULL,\n  reason       text NOT NULL,\n  changed_by   text NOT NULL,\n  changed_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX customer_segment_changes_idx ON customer_segment_changes (customer_id, changed_at DESC);\n\n-- 3. Groups: services under one account that share benefits. One Principal, any number of Supplementary services; a supplementary\n--    service cannot exist without the principal. The old customer-to-customer \"group\" links are kept, unused, under a new name.\nALTER TABLE group_memberships RENAME TO legacy_group_memberships;\nCREATE TABLE service_groups (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  shard_id    smallint NOT NULL,\n  customer_id uuid NOT NULL,\n  account_id  uuid NOT NULL,\n  name        text NOT NULL,\n  status      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','CLOSED')),\n  benefits    jsonb NOT NULL DEFAULT '{}',          -- { allowances: { dataGb, voiceMinutes, smsCount }, discountBps }\n  created_by  text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now(),\n  closed_at   timestamptz\n);\nCREATE INDEX service_groups_account_idx  ON service_groups (account_id, created_at, id) WHERE status = 'ACTIVE';\nCREATE INDEX service_groups_customer_idx ON service_groups (customer_id) WHERE status = 'ACTIVE';\nCREATE TABLE service_group_members (\n  group_id   uuid NOT NULL REFERENCES service_groups (id),\n  service_id uuid NOT NULL,\n  role       text NOT NULL CHECK (role IN ('PRINCIPAL','SUPPLEMENTARY')),\n  added_by   text,\n  added_at   timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (group_id, service_id)\n);\nCREATE UNIQUE INDEX service_group_members_service_uq ON service_group_members (service_id);                    -- a service is in at most one group\nCREATE UNIQUE INDEX service_group_members_principal_uq ON service_group_members (group_id) WHERE role = 'PRINCIPAL'; -- and a group has one principal\nCREATE INDEX customers_segment_idx ON customers (segment);\n" },
  { name: "0013_stores.sql", sql: "-- Retail stores are master data kept in the CRM. Staff, orders and stock refer to a store by its id.\nCREATE SEQUENCE store_id_seq;\nCREATE TABLE stores (\n  id          text PRIMARY KEY,                    -- issued by the system (STORE-00001); older ids are kept as they were\n  name        text NOT NULL,\n  status      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  market_code char(2),\n  address     text,\n  phone       text,\n  created_by  text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX stores_name_uq ON stores (lower(name));\nCREATE INDEX users_store_idx ON users (store_id) WHERE store_id IS NOT NULL;\n\n-- Store ids already used by staff, orders and stock become stores (named after their id until someone renames them).\nINSERT INTO stores (id, name)\n  SELECT s, s FROM (\n    SELECT store_id AS s FROM users WHERE store_id IS NOT NULL\n    UNION SELECT store_id FROM orders WHERE store_id IS NOT NULL\n    UNION SELECT location_id FROM inventory_stock WHERE location_id LIKE 'STORE-%'\n  ) x ON CONFLICT DO NOTHING;\n" },
  { name: "0014_catalog_config.sql", sql: "-- Catalog configuration (Settings → Catalog): the offer types an operator can create, and the ways an offer can be fulfilled.\n-- Both lists are data. What a type or option DOES comes from the behaviour template / mechanic it is based on, so the platform\n-- always knows how to sell, fulfil and bill it. The built-in rows below are the defaults.\nCREATE TABLE offer_types (\n  id          text PRIMARY KEY,                 -- the offer's `kind`; built-ins use their template's code\n  name        text NOT NULL,\n  description text,\n  template    text NOT NULL CHECK (template IN ('SIM_ONLY','SIM_DEVICE','WEARABLE','FIBER','IOT_CONNECTIVITY','VAS','NON_TELCO_SUBSCRIPTION','PHYSICAL_GOOD')),\n  status      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  sort_order  integer NOT NULL DEFAULT 100,\n  is_builtin  boolean NOT NULL DEFAULT false,\n  created_by  text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX offer_types_name_uq ON offer_types (lower(name));\nINSERT INTO offer_types (id, name, description, template, sort_order, is_builtin) VALUES\n  ('SIM_ONLY',               'SIM only',            'A mobile plan with a SIM and no device.',                          'SIM_ONLY',               10, true),\n  ('SIM_DEVICE',             'SIM + device',        'A mobile plan sold with a phone, usually on contract.',            'SIM_DEVICE',             20, true),\n  ('WEARABLE',               'Wearable',            'A connected watch or band.',                                       'WEARABLE',               30, true),\n  ('FIBER',                  'Fibre',               'Home fibre broadband, installed by a technician.',                 'FIBER',                  40, true),\n  ('IOT_CONNECTIVITY',       'IoT connectivity',    'Connectivity for connected devices, bought in bulk.',              'IOT_CONNECTIVITY',       50, true),\n  ('VAS',                    'Add-on',              'An extra on top of a plan: roaming, extra data, device care.',     'VAS',                    60, true),\n  ('NON_TELCO_SUBSCRIPTION', 'Partner subscription','A partner’s service billed with the plan, such as streaming.',    'NON_TELCO_SUBSCRIPTION', 70, true),\n  ('PHYSICAL_GOOD',          'Goods',               'A device or appliance sold outright.',                             'PHYSICAL_GOOD',          80, true);\n\nCREATE TABLE fulfilment_options (\n  id           text PRIMARY KEY,\n  name         text NOT NULL,\n  description  text,\n  mechanic     text NOT NULL CHECK (mechanic IN ('SHIP','COLLECT','INSTALL','SIM')),\n  tracks_stock boolean NOT NULL DEFAULT false,   -- true: offers using it list the stock SKUs reserved when sold\n  status       text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  sort_order   integer NOT NULL DEFAULT 100,\n  is_builtin   boolean NOT NULL DEFAULT false,\n  created_by   text,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  updated_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX fulfilment_options_name_uq ON fulfilment_options (lower(name));\nINSERT INTO fulfilment_options (id, name, description, mechanic, tracks_stock, sort_order, is_builtin) VALUES\n  ('SHIP',    'Delivered to the customer', 'Posted or couriered to the customer''s address.',                                  'SHIP',    true,  10, true),\n  ('COLLECT', 'Collect in store',          'The customer collects it from a store they choose.',                               'COLLECT', true,  20, true),\n  ('INSTALL', 'Installation visit',        'A technician visits to install it.',                                               'INSTALL', false, 30, true),\n  ('SIM',     'SIM activation',            'A SIM card is issued and activated. Turn on stock tracking if you count SIM cards.', 'SIM',     false, 40, true);\n\n-- Offers made before this existed get the option ids that match their old flags, so the offer wizard can show them.\nUPDATE catalog_nodes SET data = jsonb_set(data, '{fulfilment,options}',\n    to_jsonb(ARRAY_REMOVE(ARRAY[\n      CASE WHEN (data->'fulfilment'->>'requiresShipping')::boolean THEN 'SHIP' END,\n      CASE WHEN (data->'fulfilment'->>'requiresInstallation')::boolean THEN 'INSTALL' END,\n      CASE WHEN (data->'fulfilment'->>'requiresSimActivation')::boolean THEN 'SIM' END], NULL)))\n  WHERE level = 'OFFER' AND data->'fulfilment' IS NOT NULL AND data->'fulfilment' ? 'requiresShipping' AND NOT (data->'fulfilment' ? 'options');\n" },
  { name: "0015_scheduled_offers.sql", sql: "-- An offer (or any catalog node) can be scheduled to go live on a future date.\nALTER TABLE catalog_nodes DROP CONSTRAINT IF EXISTS catalog_nodes_status_check;\nALTER TABLE catalog_nodes ADD CONSTRAINT catalog_nodes_status_check CHECK (status IN ('DRAFT','SCHEDULED','ACTIVE','RETIRED'));\nALTER TABLE catalog_nodes ADD COLUMN IF NOT EXISTS active_from timestamptz;\nCREATE INDEX IF NOT EXISTS catalog_nodes_due_idx ON catalog_nodes (active_from) WHERE status = 'SCHEDULED';\n" },
  { name: "0016_device_deals.sql", sql: "-- A device bought on a contract together with a plan: which plan line it belongs to, and the contract it was bought on.\nALTER TABLE order_lines ADD COLUMN IF NOT EXISTS position smallint NOT NULL DEFAULT 0;\nALTER TABLE order_lines ADD COLUMN IF NOT EXISTS attach_position smallint;\nALTER TABLE order_lines ADD COLUMN IF NOT EXISTS deal jsonb;\n-- The plan's service remembers the contract the device was bought on, so its early-termination charge never depends on later catalog edits.\nALTER TABLE services ADD COLUMN IF NOT EXISTS deal jsonb;\n" },
  { name: "0017_customer_details.sql", sql: "-- More about a customer: date of birth, gender and a postal address (which of these the staff screens ask for is a setting).\nALTER TABLE customers ADD COLUMN IF NOT EXISTS date_of_birth date;\nALTER TABLE customers ADD COLUMN IF NOT EXISTS gender text;\nALTER TABLE customers ADD COLUMN IF NOT EXISTS address jsonb;\n" },
  { name: "0018_warehouses.sql", sql: "-- Warehouse locations are master data kept in the CRM (like stores), and every change to stock leaves a movement behind.\nCREATE SEQUENCE IF NOT EXISTS warehouse_id_seq;\nCREATE TABLE warehouses (\n  id          text PRIMARY KEY,                    -- WH-MAIN for the original; new ones are issued by the system (WH-00002 ...)\n  name        text NOT NULL,\n  status      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  address     text,\n  created_by  text,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX warehouses_name_uq ON warehouses (lower(name));\n\n-- The main warehouse, and any other non-store place that already holds stock, become warehouses.\nINSERT INTO warehouses (id, name) VALUES ('WH-MAIN', 'Main warehouse') ON CONFLICT DO NOTHING;\nINSERT INTO warehouses (id, name)\n  SELECT DISTINCT location_id, location_id FROM inventory_stock\n  WHERE location_id NOT LIKE 'STORE-%' AND location_id <> 'WH-MAIN' AND NOT EXISTS (SELECT 1 FROM stores s WHERE s.id = inventory_stock.location_id)\n  ON CONFLICT DO NOTHING;\n\nCREATE TABLE stock_movements (\n  id          bigserial PRIMARY KEY,\n  at          timestamptz NOT NULL DEFAULT now(),\n  location_id text NOT NULL,\n  sku         text NOT NULL,\n  delta       integer NOT NULL,\n  on_hand     integer NOT NULL,                    -- on hand after the movement\n  kind        text NOT NULL CHECK (kind IN ('RECEIPT','IMPORT','WRITE_OFF','COUNT')),\n  reason      text,                                -- write-offs: DAMAGED, LOST, EXPIRED, THEFT, COUNT, OTHER\n  note        text,\n  actor       text NOT NULL\n);\nCREATE INDEX stock_movements_loc_idx ON stock_movements (location_id, at DESC);\nCREATE INDEX stock_movements_sku_idx ON stock_movements (sku text_pattern_ops, at DESC);\n" },
  { name: "0019_service_lifecycle.sql", sql: "-- Service lifecycle: voluntary suspension, credit-limit and dunning bars, termination and number quarantine.\n-- (This codebase keeps its schema in SQL migrations rather than Prisma; this is the schema extension.)\n\n-- What state a service is in beyond ACTIVE/SUSPENDED/TERMINATED, and why.\nALTER TABLE services\n  ADD COLUMN IF NOT EXISTS suspension_kind text,            -- VOLUNTARY | CREDIT | DUNNING | FRAUD | ADMIN (null when not suspended)\n  ADD COLUMN IF NOT EXISTS suspended_at    timestamptz,\n  ADD COLUMN IF NOT EXISTS suspend_until   date,            -- voluntary suspensions end on this date (automatic resume)\n  ADD COLUMN IF NOT EXISTS bar_level       text NOT NULL DEFAULT 'NONE' CHECK (bar_level IN ('NONE','THROTTLE','SOFT','HARD')),\n  ADD COLUMN IF NOT EXISTS terminated_reason text;\nCREATE INDEX IF NOT EXISTS services_suspend_until_idx ON services (suspend_until) WHERE suspend_until IS NOT NULL AND status = 'SUSPENDED';\n\n-- An account's own credit limit (null = the default in Settings → Lifecycle) and the deposit held for it.\nALTER TABLE accounts\n  ADD COLUMN IF NOT EXISTS credit_limit_minor bigint,\n  ADD COLUMN IF NOT EXISTS deposit_minor bigint NOT NULL DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS credit_state text NOT NULL DEFAULT 'OK' CHECK (credit_state IN ('OK','WARNED','BLOCKED'));\nALTER TABLE invoices ADD COLUMN IF NOT EXISTS collections_at timestamptz;   -- handed to collections\nALTER TABLE invoices DROP CONSTRAINT IF EXISTS invoices_status_check;\nALTER TABLE invoices ADD CONSTRAINT invoices_status_check CHECK (status IN ('ISSUED','OVERDUE','PAID','VOID','WRITTEN_OFF'));\nDROP INDEX IF EXISTS invoices_open_idx;\nCREATE INDEX invoices_open_idx ON invoices (due_date) WHERE status IN ('ISSUED','OVERDUE');\n\n-- Every change of a service's state, who asked for it and why (the lifecycle audit log).\nCREATE TABLE service_lifecycle_events (\n  id          bigserial PRIMARY KEY,\n  at          timestamptz NOT NULL DEFAULT now(),\n  service_id  uuid NOT NULL,\n  account_id  uuid,\n  action      text NOT NULL,                  -- SUSPEND, RESUME, BAR, UNBAR, TERMINATE, PORT_OUT, CREDIT_WARNING ...\n  from_status text,\n  to_status   text,\n  kind        text,                           -- VOLUNTARY | CREDIT | DUNNING ...\n  actor       text NOT NULL,\n  detail      jsonb NOT NULL DEFAULT '{}'\n);\nCREATE INDEX service_lifecycle_service_idx ON service_lifecycle_events (service_id, at DESC);\n\n-- Periods a customer asked to be suspended: recurring charges are paused or reduced to a maintenance fee for these days, and\n-- prorated on the bill that follows the return.\nCREATE TABLE service_suspensions (\n  id            bigserial PRIMARY KEY,\n  service_id    uuid NOT NULL,\n  account_id    uuid NOT NULL,\n  started_on    date NOT NULL,\n  ends_on       date,                          -- the planned (maximum) end; null once ended early/converted\n  ended_on      date,                          -- the day service came back (null while suspended)\n  end_reason    text,                          -- RESUMED | AUTO_RESUMED | CONVERTED_TO_DUNNING | TERMINATED\n  requested_by  text NOT NULL,\n  channel       text NOT NULL DEFAULT 'STAFF'  -- STAFF | SELF_SERVE\n);\nCREATE INDEX service_suspensions_service_idx ON service_suspensions (service_id, started_on);\nCREATE INDEX service_suspensions_account_idx ON service_suspensions (account_id, started_on);\n\n-- The dunning ladder, one run per account while something is overdue; which steps have been applied.\nCREATE TABLE dunning_runs (\n  id           bigserial PRIMARY KEY,\n  account_id   uuid NOT NULL,\n  anchor_due   date NOT NULL,                  -- the due date (D) of the oldest unpaid invoice\n  status       text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','PAID','TERMINATED','CANCELLED')),\n  started_at   timestamptz NOT NULL DEFAULT now(),\n  ended_at     timestamptz,\n  workflow_id  text,\n  last_step    text\n);\nCREATE UNIQUE INDEX dunning_runs_active_uq ON dunning_runs (account_id) WHERE status = 'ACTIVE';\nCREATE TABLE dunning_steps (\n  id          bigserial PRIMARY KEY,\n  run_id      bigint NOT NULL REFERENCES dunning_runs (id),\n  step        text NOT NULL,                   -- the step code in the ladder (REMIND, SOFT_BAR, HARD_BAR, FINAL_NOTICE, TERMINATE)\n  day_offset  integer NOT NULL,\n  applied_on  date NOT NULL,\n  outcome     jsonb NOT NULL DEFAULT '{}',\n  UNIQUE (run_id, step)\n);\n\n-- A number leaves service and rests here before it can be given to anyone else.\nCREATE TABLE msisdn_quarantine (\n  identifier   text PRIMARY KEY,\n  service_id   uuid NOT NULL,\n  reason       text NOT NULL,\n  since        date NOT NULL,\n  release_on   date NOT NULL\n);\nCREATE INDEX msisdn_quarantine_release_idx ON msisdn_quarantine (release_on);\n\n-- Things that must reach other systems. Written in the same transaction as the change, delivered by an adapter\n-- (PCRF/PCF policy, HLR/HSS, SMS and email, collections, the general ledger).\nCREATE TABLE lifecycle_outbox (\n  id           bigserial PRIMARY KEY,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  kind         text NOT NULL CHECK (kind IN ('NETWORK','NOTIFY','COLLECTIONS','GL')),\n  service_id   uuid,\n  account_id   uuid,\n  instruction  text NOT NULL,                  -- THROTTLE_DATA, BAR_OUTGOING, BAR_ALL, RESTORE, DEPROVISION, REMINDER, FINAL_NOTICE ...\n  payload      jsonb NOT NULL DEFAULT '{}',\n  delivered_at timestamptz\n);\nCREATE INDEX lifecycle_outbox_pending_idx ON lifecycle_outbox (id) WHERE delivered_at IS NULL;\n\n-- Deposits move money without an order or an invoice, so a payment can belong to an account instead.\nALTER TABLE payments ADD COLUMN IF NOT EXISTS account_id uuid;\nALTER TABLE payments DROP CONSTRAINT IF EXISTS payments_target;\nALTER TABLE payments ADD CONSTRAINT payments_target CHECK (order_id IS NOT NULL OR invoice_id IS NOT NULL OR account_id IS NOT NULL);\n" },
  { name: "0020_order_numbers.sql", sql: "-- Order numbers people can read out: the order date, then a counter for that day (20261014-00042).\nALTER TABLE orders ADD COLUMN IF NOT EXISTS number text;\nCREATE TABLE IF NOT EXISTS order_counters (day date PRIMARY KEY, last integer NOT NULL);\n\n-- Orders that already exist get a number from their own date, in the order they were placed.\nUPDATE orders o SET number = n.num\n  FROM (SELECT shard_id, id, to_char(created_at, 'YYYYMMDD') || '-' || lpad((row_number() OVER (PARTITION BY created_at::date ORDER BY created_at, id))::text, 5, '0') AS num FROM orders) n\n WHERE o.shard_id = n.shard_id AND o.id = n.id AND o.number IS NULL;\nINSERT INTO order_counters (day, last)\n  SELECT created_at::date, count(*) FROM orders GROUP BY created_at::date\n  ON CONFLICT (day) DO UPDATE SET last = GREATEST(order_counters.last, EXCLUDED.last);\n-- orders is partitioned by shard, so a unique index would have to include shard_id; the counter makes numbers unique by construction.\nCREATE INDEX IF NOT EXISTS orders_number_idx ON orders (number text_pattern_ops);\n" },
  { name: "0021_numbering.sql", sql: "-- Number Resource Management: the pools of SIM serials (ICCID), subscriber identities (IMSI) and phone numbers (MSISDN),\n-- VIP number tiers and what they cost, reservations, and a trail of every state change.\n-- (The brief asked for Prisma; this codebase keeps its schema in SQL migrations, and this is that schema.)\n\n-- What a number tier costs and demands. `patterns` are the regular expressions that put a number in the tier (matched against the last 8 digits).\nCREATE TABLE msisdn_vip_tier_rules (\n  tier                   text PRIMARY KEY CHECK (tier IN ('DIAMOND','GOLD','SILVER','STANDARD','AUCTION')),\n  label                  text NOT NULL,\n  sort_order             integer NOT NULL,\n  patterns               jsonb NOT NULL DEFAULT '[]',          -- [{ \"code\": \"AAAAA\", \"regex\": \"(\\\\d)\\\\1{4,}$\" }]\n  one_time_fee_minor     bigint NOT NULL DEFAULT 0,            -- connection fee for choosing the number\n  min_monthly_plan_minor bigint NOT NULL DEFAULT 0,            -- the plan's monthly fee must be at least this\n  min_contract_months    integer NOT NULL DEFAULT 0,           -- the plan must come with a contract at least this long\n  etc_multiplier_bps     integer NOT NULL DEFAULT 10000,       -- 15000 = the early-termination charge is 1.5x\n  enabled                boolean NOT NULL DEFAULT true,\n  updated_by             text,\n  updated_at             timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE msisdn_inventory (\n  msisdn           text PRIMARY KEY,                           -- E.164\n  state            text NOT NULL DEFAULT 'AVAILABLE' CHECK (state IN ('AVAILABLE','RESERVED_CHECKOUT','ASSIGNED_ACTIVE','QUARANTINE_COOLING','BLOCKED_VIP','AUCTION_HOLD','PORTED_OUT')),\n  tier             text NOT NULL DEFAULT 'STANDARD' CHECK (tier IN ('DIAMOND','GOLD','SILVER','STANDARD','AUCTION')),\n  pattern_code     text,\n  previous_state   text,                                       -- what to go back to when a reservation lapses\n  reserved_by      text,\n  reserved_until   timestamptz,\n  service_id       uuid,\n  quarantine_until date,\n  batch            text,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX msisdn_inventory_pick_idx ON msisdn_inventory (tier, msisdn) WHERE state = 'AVAILABLE';\nCREATE INDEX msisdn_inventory_state_idx ON msisdn_inventory (state, msisdn);\nCREATE INDEX msisdn_inventory_prefix_idx ON msisdn_inventory (msisdn text_pattern_ops);\nCREATE INDEX msisdn_inventory_reserved_idx ON msisdn_inventory (reserved_until) WHERE state = 'RESERVED_CHECKOUT';\nCREATE INDEX msisdn_inventory_quarantine_idx ON msisdn_inventory (quarantine_until) WHERE state IN ('QUARANTINE_COOLING');\n\nCREATE TABLE iccid_inventory (\n  iccid            text PRIMARY KEY,\n  kind             text NOT NULL DEFAULT 'PHYSICAL' CHECK (kind IN ('PHYSICAL','ESIM')),\n  state            text NOT NULL DEFAULT 'WAREHOUSE_INVENTORY' CHECK (state IN ('WAREHOUSE_INVENTORY','DISTRIBUTED_DEALER','RESERVED','ACTIVE','DAMAGED_SCRAPPED','DECOMMISSIONED')),\n  location_id      text,                                       -- the warehouse, store or dealer holding a physical SIM\n  imsi             text,                                       -- the identity written onto it\n  activation_code  text,                                       -- eSIM: the SM-DP+ activation code (LPA:1$...)\n  batch            text,\n  order_id         uuid,\n  service_id       uuid,\n  previous_state   text,\n  reserved_until   timestamptz,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX iccid_inventory_pick_idx ON iccid_inventory (location_id, kind, iccid) WHERE state IN ('WAREHOUSE_INVENTORY','DISTRIBUTED_DEALER');\nCREATE INDEX iccid_inventory_state_idx ON iccid_inventory (state, iccid);\nCREATE INDEX iccid_inventory_order_idx ON iccid_inventory (order_id) WHERE order_id IS NOT NULL;\n\nCREATE TABLE imsi_inventory (\n  imsi             text PRIMARY KEY,\n  state            text NOT NULL DEFAULT 'POOL_UNASSIGNED' CHECK (state IN ('POOL_UNASSIGNED','BOUND_TO_SIM','ACTIVE','QUARANTINED','RECYCLED')),\n  iccid            text,\n  service_id       uuid,\n  previous_msisdn  text,\n  quarantine_until date,\n  batch            text,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX imsi_inventory_pool_idx ON imsi_inventory (imsi) WHERE state = 'POOL_UNASSIGNED';\nCREATE INDEX imsi_inventory_quarantine_idx ON imsi_inventory (quarantine_until) WHERE state = 'QUARANTINED';\n\n-- Holds on numbers and SIMs while a customer is checking out. One live hold per resource.\nCREATE TABLE number_reservation_locks (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  resource_type  text NOT NULL CHECK (resource_type IN ('MSISDN','ICCID')),\n  resource_id    text NOT NULL,\n  holder         text NOT NULL,                                -- who holds it: a checkout session, an order, an auction\n  token          text NOT NULL,\n  state          text NOT NULL DEFAULT 'ACTIVE' CHECK (state IN ('ACTIVE','CONSUMED','RELEASED','EXPIRED')),\n  expires_at     timestamptz NOT NULL,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  ended_at       timestamptz\n);\nCREATE UNIQUE INDEX number_reservation_active_uq ON number_reservation_locks (resource_type, resource_id) WHERE state = 'ACTIVE';\nCREATE INDEX number_reservation_expiry_idx ON number_reservation_locks (expires_at) WHERE state = 'ACTIVE';\n\nCREATE TABLE identifier_lifecycle_audit (\n  id             bigserial PRIMARY KEY,\n  at             timestamptz NOT NULL DEFAULT now(),\n  resource_type  text NOT NULL CHECK (resource_type IN ('MSISDN','ICCID','IMSI')),\n  resource_id    text NOT NULL,\n  from_state     text,\n  to_state       text NOT NULL,\n  actor          text NOT NULL,\n  reason         text,\n  detail         jsonb NOT NULL DEFAULT '{}'\n);\nCREATE INDEX identifier_audit_resource_idx ON identifier_lifecycle_audit (resource_type, resource_id, id DESC);\n\n-- What an order line carries: the SIM and number chosen for it, and what a VIP number added.\nALTER TABLE order_lines\n  ADD COLUMN IF NOT EXISTS iccid text,\n  ADD COLUMN IF NOT EXISTS sim_type text,\n  ADD COLUMN IF NOT EXISTS vip_tier text,\n  ADD COLUMN IF NOT EXISTS vip_fee_minor bigint NOT NULL DEFAULT 0;\n-- And what the service keeps: its IMSI, and the VIP terms that apply if it ends early.\nALTER TABLE services\n  ADD COLUMN IF NOT EXISTS imsi text,\n  ADD COLUMN IF NOT EXISTS vip_tier text,\n  ADD COLUMN IF NOT EXISTS vip_etc_bps integer;\n\n-- The outbox also carries domain events for the message bus (Kafka): VIP_NUMBER_AUCTION_WON and friends.\nALTER TABLE lifecycle_outbox DROP CONSTRAINT IF EXISTS lifecycle_outbox_kind_check;\nALTER TABLE lifecycle_outbox ADD CONSTRAINT lifecycle_outbox_kind_check CHECK (kind IN ('NETWORK','NOTIFY','COLLECTIONS','GL','EVENT'));\n\nINSERT INTO msisdn_vip_tier_rules (tier, label, sort_order, patterns, one_time_fee_minor, min_monthly_plan_minor, min_contract_months, etc_multiplier_bps) VALUES\n  ('DIAMOND',  'Platinum / Diamond', 1, '[{\"code\":\"AAAAA\",\"regex\":\"(\\\\d)\\\\1{4,}$\"},{\"code\":\"123456\",\"regex\":\"(?:0123456|1234567|2345678|3456789|012345|123456|234567|345678|456789)$\"},{\"code\":\"654321\",\"regex\":\"(?:9876543|8765432|7654321|6543210|987654|876543|765432|654321|543210)$\"}]', 100000, 8000, 24, 15000),\n  ('GOLD',     'Gold',               2, '[{\"code\":\"AABBCC\",\"regex\":\"(\\\\d)\\\\1(\\\\d)\\\\2(\\\\d)\\\\3$\"},{\"code\":\"ABABAB\",\"regex\":\"(\\\\d)(\\\\d)\\\\1\\\\2\\\\1\\\\2$\"},{\"code\":\"AAAA\",\"regex\":\"(\\\\d)\\\\1{3}$\"}]', 30000, 5000, 12, 12500),\n  ('SILVER',   'Silver',             3, '[{\"code\":\"AABB\",\"regex\":\"(\\\\d)\\\\1(\\\\d)\\\\2$\"},{\"code\":\"ABAB\",\"regex\":\"(\\\\d)(\\\\d)\\\\1\\\\2$\"},{\"code\":\"ABABCC\",\"regex\":\"(\\\\d)(\\\\d)\\\\1\\\\2(\\\\d)\\\\3$\"},{\"code\":\"1234\",\"regex\":\"(?:0123|1234|2345|3456|4567|5678|6789|9876|8765|7654|6543|5432|4321|3210)$\"}]', 5000, 0, 0, 10000),\n  ('STANDARD', 'Standard',           4, '[]', 0, 0, 0, 10000),\n  ('AUCTION',  'Auction / special VIP', 0, '[{\"code\":\"AAAAAAAA\",\"regex\":\"(\\\\d)\\\\1{7,}$\"}]', 0, 0, 24, 20000);\n" },
  { name: "0022_group_offers_port_in.sql", sql: "-- Group plans (family / multi-line shares) and number portability into the operator (port-in).\n-- Offers keep their group terms in catalog_nodes.data.group { isGroupOffer, maxGroupMembers, allowedMemberOfferIds, sharedPoolQuotaGb }.\n-- A \"customer group\" is service_groups, and its member mapping is service_group_members; the Principal is the family head (group admin).\n\nALTER TABLE service_groups\n  ADD COLUMN IF NOT EXISTS offer_id         text,       -- the group plan it was made for\n  ADD COLUMN IF NOT EXISTS max_supplementary integer,   -- slots besides the family head; null = no limit\n  ADD COLUMN IF NOT EXISTS origin           text NOT NULL DEFAULT 'MANUAL' CHECK (origin IN ('MANUAL','CHECKOUT','PLAN_CHANGE'));\n\n-- What an order line is for: a member of the group the head line opens (position of the head line), or of a group that exists already.\nALTER TABLE order_lines\n  ADD COLUMN IF NOT EXISTS service_id          uuid,\n  ADD COLUMN IF NOT EXISTS group_head_position integer,\n  ADD COLUMN IF NOT EXISTS join_group_id       uuid,\n  ADD COLUMN IF NOT EXISTS port_in             jsonb;    -- donor details when the line brings a number from another operator\n\n-- A service's number may be temporary while its port-in is processed, and the service points at its request.\nALTER TABLE services\n  ADD COLUMN IF NOT EXISTS number_status text CHECK (number_status IN ('TEMPORARY','PORTED_IN')),\n  ADD COLUMN IF NOT EXISTS port_in_id    uuid;\n\nCREATE TABLE port_in_requests (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now(),\n  status           text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','COMPLETED','REJECTED','CANCELLED','EXPIRED')),\n  customer_id      uuid NOT NULL,\n  order_id         uuid,\n  order_line_id    uuid,\n  service_id       uuid,\n  donor_operator   text NOT NULL,\n  donor_msisdn     text NOT NULL,                      -- the number being brought in, E.164\n  holder_name      text NOT NULL,                      -- the account holder at the donor operator\n  holder_id_type   text NOT NULL,\n  holder_id_number text NOT NULL,\n  temporary_msisdn text,                               -- a number from our pool the customer uses while the port is processed\n  clearinghouse_ref text,\n  requested_swap_at timestamptz,                       -- the date the donor agreed to release the number\n  decided_at       timestamptz,\n  completed_at     timestamptz,\n  failure_reason   text,\n  created_by       text\n);\nCREATE INDEX port_in_requests_status_idx ON port_in_requests (status, created_at);\nCREATE INDEX port_in_requests_service_idx ON port_in_requests (service_id);\nCREATE INDEX port_in_requests_customer_idx ON port_in_requests (customer_id, created_at);\n-- A number can have only one live request at a time.\nCREATE UNIQUE INDEX port_in_requests_live_number_uq ON port_in_requests (donor_msisdn) WHERE status IN ('PENDING','APPROVED');\n" },
  { name: "0023_donor_operators.sql", sql: "-- The operators numbers can be ported in from, maintained in Settings. Each has a routing code the clearinghouse uses to route the request.\nCREATE TABLE donor_operators (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name         text NOT NULL,\n  routing_code text NOT NULL,\n  status       text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  updated_at   timestamptz NOT NULL DEFAULT now(),\n  updated_by   text\n);\nCREATE UNIQUE INDEX donor_operators_name_uq ON donor_operators (lower(name));\nCREATE UNIQUE INDEX donor_operators_code_uq ON donor_operators (lower(routing_code));\n\n-- A request keeps the operator as it was when the request was raised.\nALTER TABLE port_in_requests\n  ADD COLUMN IF NOT EXISTS donor_operator_id uuid,\n  ADD COLUMN IF NOT EXISTS donor_routing_code text;\n" },
  { name: "0024_mnp_operator_id.sql", sql: "-- What was called a \"routing code\" is the operator ID used for mobile number portability (MNP).\nALTER TABLE donor_operators RENAME COLUMN routing_code TO mnp_operator_id;\nALTER INDEX donor_operators_code_uq RENAME TO donor_operators_mnp_id_uq;\nALTER TABLE port_in_requests RENAME COLUMN donor_routing_code TO donor_mnp_operator_id;\n" },
  { name: "0025_donor_operator_id_not_unique.sql", sql: "-- An operator's MNP operator ID may be shared by more than one operator, so it is no longer unique. The name stays unique.\nDROP INDEX IF EXISTS donor_operators_mnp_id_uq;\n" },
  { name: "0026_sub_ledger_sap.sql", sql: "-- BSS sub-ledger and SAP journal export.\n--  * gl_entries becomes the immutable, monthly-partitioned financial sub-ledger (double-entry lines; every journal balances).\n--  * ledger_events makes event ingestion idempotent; ledger_dead_letters keeps events that could not be posted.\n--  * coa_mappings lets Finance decide, without a deployment, which SAP account / cost centre / profit centre a ledger line goes to.\n--  * gl_batches records each journal run (a JournalBatchRun); the exact file that was produced is kept in journal_batch_files.\n--  * reconciliation_reports / reconciliation_exceptions hold the cross-check of the ledger against what was exported and what SAP acknowledged.\n\nALTER TABLE invoice_lines ADD COLUMN IF NOT EXISTS stream text;\n\n-- ───────── the sub-ledger: partitioned by posting month ─────────\nALTER TABLE gl_entries RENAME TO gl_entries_old;\nDROP INDEX IF EXISTS gl_entries_unexported_idx;\nDROP INDEX IF EXISTS gl_entries_source_idx;\nCREATE SEQUENCE gl_entry_seq;\nCREATE TABLE gl_entries (\n  id            bigint NOT NULL DEFAULT nextval('gl_entry_seq'),\n  journal_id    uuid NOT NULL,                   -- all lines of one business event share a journal and must balance\n  entry_date    date NOT NULL,\n  source_type   text NOT NULL,                   -- ORDER | INVOICE | PAYMENT | CREDIT_NOTE | REFUND | DEPOSIT | WRITE_OFF | EVENT\n  source_id     text NOT NULL,\n  account_code  text NOT NULL,                   -- the BSS account; Finance's posting rules turn it into a SAP account at export\n  description   text NOT NULL,\n  debit_minor   bigint NOT NULL DEFAULT 0 CHECK (debit_minor >= 0),\n  credit_minor  bigint NOT NULL DEFAULT 0 CHECK (credit_minor >= 0),\n  currency      char(3) NOT NULL,\n  exported_batch_id uuid REFERENCES gl_batches(id),\n  stream        text,                            -- revenue stream: SUBSCRIPTION, USAGE, DEVICE_INSTALMENT, THIRD_PARTY, ETC, GOODS, ONE_TIME\n  event_type    text,                            -- INVOICE_GENERATED, PAYMENT_SUCCESS, ADJUSTMENT_POSTED, ETC_CHARGED ...\n  event_id      text,                            -- the idempotency key of an ingested event\n  posted_at     timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (id, entry_date),\n  CHECK ((debit_minor = 0) <> (credit_minor = 0))\n) PARTITION BY RANGE (entry_date);\n\n-- Monthly partitions from the oldest entry (or this month) to three years ahead, and a default partition so a stray date never fails a posting.\nDO $$\nDECLARE m date; last date;\nBEGIN\n  m := date_trunc('month', LEAST(COALESCE((SELECT min(entry_date) FROM gl_entries_old), current_date), current_date))::date;\n  last := (date_trunc('month', current_date) + interval '36 months')::date;\n  WHILE m <= last LOOP\n    EXECUTE format('CREATE TABLE gl_entries_p%s PARTITION OF gl_entries FOR VALUES FROM (%L) TO (%L)', to_char(m, 'YYYYMM'), m, (m + interval '1 month')::date);\n    m := (m + interval '1 month')::date;\n  END LOOP;\nEND $$;\nCREATE TABLE gl_entries_default PARTITION OF gl_entries DEFAULT;\n\nINSERT INTO gl_entries (id, journal_id, entry_date, source_type, source_id, account_code, description, debit_minor, credit_minor, currency, exported_batch_id, event_type)\nSELECT id, journal_id, entry_date, source_type, source_id, account_code, description, debit_minor, credit_minor, currency, exported_batch_id,\n       CASE source_type WHEN 'INVOICE' THEN 'INVOICE_GENERATED' WHEN 'PAYMENT' THEN 'PAYMENT_SUCCESS' WHEN 'CREDIT_NOTE' THEN 'ADJUSTMENT_POSTED'\n                        WHEN 'REFUND' THEN 'REFUND_POSTED' WHEN 'ORDER' THEN 'ORDER_PAID' WHEN 'DEPOSIT' THEN 'DEPOSIT_RECEIVED' WHEN 'WRITE_OFF' THEN 'WRITE_OFF' ELSE source_type END\n  FROM gl_entries_old;\nSELECT setval('gl_entry_seq', GREATEST((SELECT COALESCE(max(id), 0) FROM gl_entries), 1));\nDROP TABLE gl_entries_old;\n\nCREATE INDEX gl_entries_unexported_idx ON gl_entries (entry_date) WHERE exported_batch_id IS NULL;\nCREATE INDEX gl_entries_source_idx ON gl_entries (source_type, source_id);\nCREATE INDEX gl_entries_journal_idx ON gl_entries (journal_id);\nCREATE INDEX gl_entries_account_idx ON gl_entries (account_code, entry_date);\nCREATE INDEX gl_entries_batch_idx ON gl_entries (exported_batch_id) WHERE exported_batch_id IS NOT NULL;\n\n-- Immutable: a posted line is never changed or deleted. The one allowed update is stamping it with the batch that exported it, once.\nCREATE FUNCTION gl_entries_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    RAISE EXCEPTION 'ledger entries are immutable: post a reversing journal instead' USING ERRCODE = 'integrity_constraint_violation';\n  END IF;\n  IF OLD.exported_batch_id IS NULL AND NEW.exported_batch_id IS NOT NULL\n     AND (NEW.id, NEW.journal_id, NEW.entry_date, NEW.source_type, NEW.source_id, NEW.account_code, NEW.description, NEW.debit_minor, NEW.credit_minor, NEW.currency, NEW.stream, NEW.event_type, NEW.event_id, NEW.posted_at)\n         IS NOT DISTINCT FROM\n         (OLD.id, OLD.journal_id, OLD.entry_date, OLD.source_type, OLD.source_id, OLD.account_code, OLD.description, OLD.debit_minor, OLD.credit_minor, OLD.currency, OLD.stream, OLD.event_type, OLD.event_id, OLD.posted_at) THEN\n    RETURN NEW;\n  END IF;\n  RAISE EXCEPTION 'ledger entries are immutable: post a reversing journal instead' USING ERRCODE = 'integrity_constraint_violation';\nEND $$;\nCREATE TRIGGER gl_entries_immutable BEFORE UPDATE OR DELETE ON gl_entries FOR EACH ROW EXECUTE FUNCTION gl_entries_guard();\n\n-- ───────── event ingestion ─────────\nCREATE TABLE ledger_events (\n  event_id     text PRIMARY KEY,                 -- the sender's id: the same event delivered twice posts once\n  event_type   text NOT NULL,\n  payload_hash text NOT NULL,                    -- the same id with a different payload is an error, not a duplicate\n  journal_id   uuid,\n  source       text NOT NULL DEFAULT 'API',      -- API | KAFKA | MODULE\n  received_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE TABLE ledger_dead_letters (\n  id          bigserial PRIMARY KEY,\n  received_at timestamptz NOT NULL DEFAULT now(),\n  topic       text,\n  message_key text,\n  payload     text NOT NULL,\n  error       text NOT NULL,\n  resolved_at timestamptz\n);\nCREATE INDEX ledger_dead_letters_open_idx ON ledger_dead_letters (id) WHERE resolved_at IS NULL;\n\n-- ───────── chart of accounts mapping (posting rules) ─────────\nCREATE TABLE coa_mappings (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name           text NOT NULL,\n  priority       integer NOT NULL DEFAULT 100,    -- lower wins between rules that match equally well\n  match_account  text,                            -- the BSS account (null = any)\n  match_stream   text,                            -- the revenue stream (null = any, including lines with no stream)\n  match_event    text,                            -- the event type (null = any)\n  match_source   text,                            -- the source type (null = any)\n  sap_account    text NOT NULL,                   -- SAP G/L account\n  cost_center    text,\n  profit_center  text,\n  tax_code       text,\n  status         text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  valid_from     date,\n  valid_to       date,\n  note           text,\n  created_by     text,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  updated_at     timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX coa_mappings_active_idx ON coa_mappings (status, priority);\n\n-- Sample starting rules. The SAP accounts, cost centres and profit centres are placeholders: Finance replaces them with the company's own in Finance → Posting rules.\nINSERT INTO coa_mappings (name, match_account, match_stream, sap_account, cost_center, profit_center, priority, note, created_by) VALUES\n ('Cash and bank',                 '1100', NULL,                '113100', NULL,      NULL,        100, 'sample', 'system'),\n ('Accounts receivable',           '1200', NULL,                '121000', NULL,      NULL,        100, 'sample', 'system'),\n ('Indirect tax payable',          '2100', NULL,                '217000', NULL,      NULL,        100, 'sample', 'system'),\n ('Customer deposits',             '2200', NULL,                '228000', NULL,      NULL,        100, 'sample', 'system'),\n ('Bad debt expense',              '6100', NULL,                '650100', 'CC-FIN',  NULL,        100, 'sample', 'system'),\n ('Credit notes and refunds',      '4900', NULL,                '490000', NULL,      'PC-MOBILE', 100, 'sample', 'system'),\n ('Service revenue (other)',       '4000', NULL,                '400000', NULL,      'PC-MOBILE', 100, 'sample', 'system'),\n ('Subscription revenue',          '4000', 'SUBSCRIPTION',      '400100', NULL,      'PC-MOBILE', 100, 'sample', 'system'),\n ('Voice and data usage revenue',  '4000', 'USAGE',             '400200', NULL,      'PC-MOBILE', 100, 'sample', 'system'),\n ('One-time service fees',         '4000', 'ONE_TIME',          '400300', NULL,      'PC-MOBILE', 100, 'sample', 'system'),\n ('Third-party digital content',   '4000', 'THIRD_PARTY',       '420100', NULL,      'PC-DIGITAL',100, 'sample', 'system'),\n ('Early termination fees',        '4000', 'ETC',               '440100', NULL,      'PC-MOBILE', 100, 'sample', 'system'),\n ('Goods revenue (other)',         '4100', NULL,                '410000', NULL,      'PC-DEVICES',100, 'sample', 'system'),\n ('Device sales',                  '4100', 'GOODS',             '410100', NULL,      'PC-DEVICES',100, 'sample', 'system'),\n ('Device instalments',            '4100', 'DEVICE_INSTALMENT', '410200', NULL,      'PC-DEVICES',100, 'sample', 'system');\n\n-- ───────── journal batch runs ─────────\nALTER TABLE gl_batches\n  ADD COLUMN IF NOT EXISTS run_type        text NOT NULL DEFAULT 'MANUAL' CHECK (run_type IN ('SCHEDULED','MANUAL','REALTIME')),\n  ADD COLUMN IF NOT EXISTS format          text NOT NULL DEFAULT 'CSV'    CHECK (format IN ('CSV','FLAT','IDOC','JSON')),\n  ADD COLUMN IF NOT EXISTS status          text NOT NULL DEFAULT 'COMPLETED' CHECK (status IN ('COMPLETED','FAILED')),\n  ADD COLUMN IF NOT EXISTS period_from     date,\n  ADD COLUMN IF NOT EXISTS period_to       date,\n  ADD COLUMN IF NOT EXISTS document_count  integer NOT NULL DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS file_name       text,\n  ADD COLUMN IF NOT EXISTS file_sha256     text,\n  ADD COLUMN IF NOT EXISTS delivery_status text NOT NULL DEFAULT 'NOT_SENT' CHECK (delivery_status IN ('NOT_SENT','DELIVERED','FAILED')),\n  ADD COLUMN IF NOT EXISTS delivery_detail text,\n  ADD COLUMN IF NOT EXISTS sap_reference   text,\n  ADD COLUMN IF NOT EXISTS sap_debit_minor bigint,\n  ADD COLUMN IF NOT EXISTS sap_credit_minor bigint,\n  ADD COLUMN IF NOT EXISTS acknowledged_at timestamptz,\n  ADD COLUMN IF NOT EXISTS error           text,\n  ADD COLUMN IF NOT EXISTS created_by      text;\nCREATE SEQUENCE gl_batch_seq;\nALTER TABLE gl_batches ADD COLUMN IF NOT EXISTS batch_no text;\nUPDATE gl_batches SET batch_no = 'M' || lpad(nextval('gl_batch_seq')::text, 7, '0') WHERE batch_no IS NULL;\nCREATE TABLE journal_batch_files (\n  batch_id     uuid PRIMARY KEY REFERENCES gl_batches(id),\n  content      text NOT NULL,\n  content_type text NOT NULL,\n  totals       jsonb NOT NULL DEFAULT '{}',   -- what the exporter computed when it wrote the file, per SAP account\n  ack          jsonb                          -- what SAP reported back (totals, per account)\n);\n\n-- ───────── reconciliation ─────────\nCREATE TABLE reconciliation_reports (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  scope         text NOT NULL CHECK (scope IN ('BATCH','PERIOD')),\n  batch_id      uuid REFERENCES gl_batches(id),\n  period_from   date,\n  period_to     date,\n  status        text NOT NULL CHECK (status IN ('OK','MISMATCH')),\n  ledger_debit_minor  bigint NOT NULL DEFAULT 0,\n  ledger_credit_minor bigint NOT NULL DEFAULT 0,\n  file_debit_minor    bigint,\n  file_credit_minor   bigint,\n  sap_debit_minor     bigint,\n  sap_credit_minor    bigint,\n  exception_count integer NOT NULL DEFAULT 0,\n  created_by    text\n);\nCREATE INDEX reconciliation_reports_idx ON reconciliation_reports (created_at DESC);\nCREATE INDEX reconciliation_reports_batch_idx ON reconciliation_reports (batch_id);\nCREATE TABLE reconciliation_exceptions (\n  id          bigserial PRIMARY KEY,\n  report_id   uuid NOT NULL REFERENCES reconciliation_reports(id),\n  code        text NOT NULL,                     -- RECONCILIATION_MISMATCH, UNMAPPED_ACCOUNT, NOT_ACKNOWLEDGED, UNEXPORTED_ENTRIES, UNBALANCED_JOURNAL ...\n  severity    text NOT NULL DEFAULT 'ERROR' CHECK (severity IN ('ERROR','WARNING')),\n  subject     text,                              -- the account, batch or day it is about\n  expected_minor bigint,\n  actual_minor   bigint,\n  detail      text NOT NULL\n);\nCREATE INDEX reconciliation_exceptions_report_idx ON reconciliation_exceptions (report_id);\n" },
  { name: "0027_commission.sql", sql: "-- Dealer and sales-agent commission: channel hierarchy, configurable plans (rules, volume slabs, claw-back policies), an append-only earnings ledger,\n-- monthly settlement statements and bank / payroll payout files. Earnings and payouts post to the GL, so Finance's posting rules carry them to SAP.\n-- (The brief asked for Prisma; this codebase keeps its schema in SQL migrations, and this is that schema.)\n\n-- ───────── channel hierarchy: master distributors, dealers, sub-dealers, franchise outlets ─────────\nALTER TABLE dealers\n  ADD COLUMN tier              text NOT NULL DEFAULT 'DEALER' CHECK (tier IN ('MASTER_DISTRIBUTOR','DEALER','SUB_DEALER','FRANCHISE')),\n  ADD COLUMN parent_dealer_id  text REFERENCES dealers(id),\n  ADD COLUMN bank_account_name text,\n  ADD COLUMN bank_account_no   text,\n  ADD COLUMN bank_code         text,\n  ADD COLUMN sap_vendor_no     text;                 -- the dealer's vendor account in SAP accounts payable\nCREATE INDEX dealers_parent_idx ON dealers (parent_dealer_id) WHERE parent_dealer_id IS NOT NULL;\n\n-- ───────── plans, rules, claw-back policies ─────────\nCREATE TABLE commission_plans (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name          text NOT NULL,\n  status        text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  valid_from    date,\n  valid_to      date,\n  hold_days     integer NOT NULL DEFAULT 0 CHECK (hold_days >= 0),   -- days an earning stays PENDING before it is approved for payment\n  override_bps  jsonb NOT NULL DEFAULT '[]',                         -- what each level of upline earns on the sale: [parent, grandparent, ...] in basis points of the basis\n  note          text,\n  created_by    text,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_at    timestamptz NOT NULL DEFAULT now()\n);\nCREATE TABLE commission_rules (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  plan_id         uuid NOT NULL REFERENCES commission_plans(id) ON DELETE CASCADE,\n  name            text NOT NULL,\n  priority        integer NOT NULL DEFAULT 100,                      -- lower wins between rules that match equally well\n  match_kinds     jsonb NOT NULL DEFAULT '[]',                       -- offer kinds, empty = any\n  match_offer_ids jsonb NOT NULL DEFAULT '[]',                       -- specific offers, empty = any\n  min_term_months integer,                                           -- contract length: 0 = SIM-only, 24 = a 24-month contract; null = no limit\n  max_term_months integer,\n  match_tiers     jsonb NOT NULL DEFAULT '[]',                       -- seller tiers (MASTER_DISTRIBUTOR, DEALER, ...), empty = any\n  calc            text NOT NULL DEFAULT 'PERCENT' CHECK (calc IN ('PERCENT','FIXED')),\n  rate_bps        integer NOT NULL DEFAULT 0 CHECK (rate_bps >= 0),\n  fixed_minor     bigint  NOT NULL DEFAULT 0 CHECK (fixed_minor >= 0),\n  slab_mode       text NOT NULL DEFAULT 'MARGINAL' CHECK (slab_mode IN ('MARGINAL','RETROACTIVE')),\n  slabs           jsonb NOT NULL DEFAULT '[]',                       -- [{ \"from\": 1, \"to\": 50, \"rateBps\": 500 }, ...] counted in activations per month\n  status          text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  updated_at      timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX commission_rules_plan_idx ON commission_rules (plan_id, priority);\nCREATE TABLE clawback_policies (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  plan_id           uuid NOT NULL REFERENCES commission_plans(id) ON DELETE CASCADE,\n  name              text NOT NULL,\n  min_term_months   integer,                                         -- applies to contracts of at least this length (null = all)\n  triggers          jsonb NOT NULL DEFAULT '[\"TERMINATION\",\"PORT_OUT\",\"ORDER_CANCELLED\"]',\n  tiers             jsonb NOT NULL DEFAULT '[]',                     -- [{ \"withinDays\": 30, \"percentBps\": 10000 }, { \"withinDays\": 90, \"percentBps\": 5000 }]\n  include_overrides boolean NOT NULL DEFAULT true,\n  status            text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX clawback_policies_plan_idx ON clawback_policies (plan_id);\n-- Who earns by which plan: a dealer (and, below it, its sub-dealers), a staff salesperson, a store, or a whole channel.\nCREATE TABLE commission_assignments (\n  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  plan_id    uuid NOT NULL REFERENCES commission_plans(id) ON DELETE CASCADE,\n  kind       text NOT NULL CHECK (kind IN ('DEALER','STAFF','STORE','CHANNEL')),\n  actor_id   text NOT NULL,\n  created_by text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (kind, actor_id)\n);\n\n-- ───────── the earnings ledger (append-only apart from status and the claw-back bookkeeping) ─────────\nCREATE TABLE agent_ledger_entries (\n  id               bigserial PRIMARY KEY,\n  beneficiary_kind text NOT NULL CHECK (beneficiary_kind IN ('DEALER','STAFF','STORE','HOUSE')),\n  beneficiary_id   text NOT NULL,\n  dealer_id        text,\n  dealer_agent_id  text,\n  store_id         text,\n  entry_type       text NOT NULL CHECK (entry_type IN ('EARNING','OVERRIDE','ACCELERATOR','BONUS','CLAWBACK','ADJUSTMENT')),\n  status           text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','CLAWED_BACK','PAID')),\n  amount_minor     bigint NOT NULL,                                   -- negative for a claw-back\n  basis_minor      bigint NOT NULL DEFAULT 0,\n  rate_bps         integer,\n  units            integer NOT NULL DEFAULT 0,                        -- activations this entry counts toward the slabs\n  currency         char(3) NOT NULL,\n  plan_id          uuid,\n  rule_id          uuid,\n  order_id         uuid,\n  order_line_id    uuid,\n  offer_id         text,\n  period           text NOT NULL,                                     -- YYYY-MM the earning counts in\n  earned_on        date NOT NULL,\n  approved_at      timestamptz,\n  paid_at          timestamptz,\n  settlement_id    uuid,\n  reverses_id      bigint REFERENCES agent_ledger_entries(id),\n  clawed_units     integer NOT NULL DEFAULT 0,\n  clawed_minor     bigint NOT NULL DEFAULT 0,\n  note             text,\n  calc             jsonb NOT NULL DEFAULT '{}',                       -- how the amount was worked out: the rule, slab and numbers\n  created_at       timestamptz NOT NULL DEFAULT now()\n);\n-- The same sale line can only earn once for the same beneficiary.\nCREATE UNIQUE INDEX agent_ledger_once_uq ON agent_ledger_entries (order_line_id, entry_type, beneficiary_kind, beneficiary_id) WHERE entry_type IN ('EARNING','OVERRIDE') AND order_line_id IS NOT NULL;\nCREATE UNIQUE INDEX agent_ledger_bonus_uq ON agent_ledger_entries (rule_id, beneficiary_kind, beneficiary_id, period) WHERE entry_type = 'BONUS';\nCREATE INDEX agent_ledger_beneficiary_idx ON agent_ledger_entries (beneficiary_kind, beneficiary_id, period, status);\nCREATE INDEX agent_ledger_order_idx ON agent_ledger_entries (order_id);\nCREATE INDEX agent_ledger_open_idx ON agent_ledger_entries (earned_on) WHERE status IN ('PENDING','APPROVED');\nCREATE INDEX agent_ledger_settlement_idx ON agent_ledger_entries (settlement_id) WHERE settlement_id IS NOT NULL;\n\n-- Nothing about what was earned can change afterwards: no deletes, and an entry's amount, beneficiary, order and rule are fixed. Only its status, the\n-- approval, payment and settlement stamps, and the claw-back bookkeeping move. A correction is a new entry.\nCREATE FUNCTION agent_ledger_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'commission ledger entries cannot be deleted; post a correcting entry'; END IF;\n  IF (NEW.id, NEW.beneficiary_kind, NEW.beneficiary_id, NEW.entry_type, NEW.amount_minor, NEW.basis_minor, NEW.units, NEW.currency, NEW.order_id, NEW.order_line_id, NEW.period, NEW.earned_on, NEW.plan_id, NEW.rule_id, NEW.reverses_id)\n     IS DISTINCT FROM\n     (OLD.id, OLD.beneficiary_kind, OLD.beneficiary_id, OLD.entry_type, OLD.amount_minor, OLD.basis_minor, OLD.units, OLD.currency, OLD.order_id, OLD.order_line_id, OLD.period, OLD.earned_on, OLD.plan_id, OLD.rule_id, OLD.reverses_id)\n  THEN RAISE EXCEPTION 'a commission ledger entry cannot be edited; post a correcting entry'; END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER agent_ledger_immutable BEFORE UPDATE OR DELETE ON agent_ledger_entries FOR EACH ROW EXECUTE FUNCTION agent_ledger_guard();\n\n-- ───────── statements and payouts ─────────\nCREATE SEQUENCE commission_statement_seq;\nCREATE SEQUENCE commission_payout_seq;\nCREATE TABLE commission_periods (\n  period     text PRIMARY KEY,\n  closed_at  timestamptz NOT NULL DEFAULT now(),\n  closed_by  text NOT NULL,\n  statements integer NOT NULL DEFAULT 0\n);\nCREATE TABLE commission_payout_batches (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  batch_no        text NOT NULL UNIQUE,\n  period          text NOT NULL,\n  status          text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','PAID')),\n  file_name       text NOT NULL,\n  content         text NOT NULL,\n  content_type    text NOT NULL DEFAULT 'text/csv',\n  file_sha256     text NOT NULL,\n  total_minor     bigint NOT NULL,\n  statement_count integer NOT NULL,\n  currency        char(3) NOT NULL,\n  created_by      text,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  paid_at         timestamptz,\n  confirmed_by    text\n);\nCREATE TABLE commission_settlements (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  statement_no     text NOT NULL UNIQUE,\n  period           text NOT NULL,\n  beneficiary_kind text NOT NULL,\n  beneficiary_id   text NOT NULL,\n  beneficiary_name text NOT NULL,\n  payout_method    text NOT NULL CHECK (payout_method IN ('BANK','PAYROLL','HOUSE')),\n  gross_minor      bigint NOT NULL,                                   -- earnings, overrides, accelerators and bonuses\n  clawback_minor   bigint NOT NULL,                                   -- claw-backs netted in (zero or negative)\n  net_minor        bigint NOT NULL,\n  entry_count      integer NOT NULL,\n  currency         char(3) NOT NULL,\n  status           text NOT NULL DEFAULT 'ISSUED' CHECK (status IN ('ISSUED','PAYOUT_PENDING','PAID')),\n  payout_batch_id  uuid REFERENCES commission_payout_batches(id),\n  issued_at        timestamptz NOT NULL DEFAULT now(),\n  paid_at          timestamptz\n);\nCREATE INDEX commission_settlements_period_idx ON commission_settlements (period, beneficiary_kind, beneficiary_id);\n\n-- ───────── the commission already accrued by the earlier flat-rate engine becomes ledger entries ─────────\nINSERT INTO agent_ledger_entries (beneficiary_kind, beneficiary_id, dealer_id, store_id, entry_type, status, amount_minor, basis_minor, rate_bps, units, currency, order_id, period, earned_on, approved_at, paid_at, note)\nSELECT CASE WHEN dealer_id IS NOT NULL THEN 'DEALER' WHEN salesperson_id IS NOT NULL THEN 'STAFF' ELSE 'STORE' END,\n       COALESCE(dealer_id, salesperson_id, store_id, 'HOUSE'), dealer_id, store_id, 'EARNING',\n       CASE status WHEN 'PAID' THEN 'PAID' WHEN 'CLAWED_BACK' THEN 'CLAWED_BACK' ELSE 'APPROVED' END,\n       amount_minor, basis_minor, rate_bps, 0, currency, order_id, to_char(created_at, 'YYYY-MM'), created_at::date, created_at,\n       CASE WHEN status = 'PAID' THEN created_at END, 'Carried over from the flat-rate commission table'\n  FROM commissions;\n\n-- ───────── starting plan: what the flat rates paid, so nothing changes until Finance edits it ─────────\nWITH p AS (INSERT INTO commission_plans (name, note, created_by) VALUES ('Standard commission', 'Starting plan: the flat rates by channel. Edit it or add plans in Commission → Plans.', 'system') RETURNING id),\n     r AS (INSERT INTO commission_rules (plan_id, name, rate_bps) SELECT id, 'Percent of sale value', 300 FROM p RETURNING plan_id),\n     c AS (INSERT INTO clawback_policies (plan_id, name, tiers) SELECT id, 'Early churn', '[{\"withinDays\":30,\"percentBps\":10000},{\"withinDays\":90,\"percentBps\":5000}]' FROM p RETURNING plan_id)\nINSERT INTO commission_assignments (plan_id, kind, actor_id, created_by) SELECT id, 'CHANNEL', ch, 'system' FROM p, (VALUES ('RETAIL_ASSISTED'), ('DEALER'), ('TELESALES')) AS v(ch);\n-- The earlier engine paid 3% retail, 5% dealer, 4% telesales: one rule per channel plan would need three plans, so the dealer and telesales rates are separate plans.\nWITH d AS (INSERT INTO commission_plans (name, note, created_by) VALUES ('Dealer commission', 'Starting plan for the DEALER channel.', 'system') RETURNING id),\n     dr AS (INSERT INTO commission_rules (plan_id, name, rate_bps) SELECT id, 'Percent of sale value', 500 FROM d RETURNING plan_id),\n     dc AS (INSERT INTO clawback_policies (plan_id, name, tiers) SELECT id, 'Early churn', '[{\"withinDays\":30,\"percentBps\":10000},{\"withinDays\":90,\"percentBps\":5000}]' FROM d RETURNING plan_id)\nUPDATE commission_assignments a SET plan_id = d.id FROM d WHERE a.kind = 'CHANNEL' AND a.actor_id = 'DEALER';\nWITH t AS (INSERT INTO commission_plans (name, note, created_by) VALUES ('Telesales commission', 'Starting plan for the TELESALES channel.', 'system') RETURNING id),\n     tr AS (INSERT INTO commission_rules (plan_id, name, rate_bps) SELECT id, 'Percent of sale value', 400 FROM t RETURNING plan_id),\n     tc AS (INSERT INTO clawback_policies (plan_id, name, tiers) SELECT id, 'Early churn', '[{\"withinDays\":30,\"percentBps\":10000},{\"withinDays\":90,\"percentBps\":5000}]' FROM t RETURNING plan_id)\nUPDATE commission_assignments a SET plan_id = t.id FROM t WHERE a.kind = 'CHANNEL' AND a.actor_id = 'TELESALES';\n\n-- ───────── GL: commission expense, payable and the disbursement clearing account, with sample SAP mappings ─────────\nINSERT INTO coa_mappings (name, match_account, sap_account, cost_center, profit_center, priority, note, created_by) VALUES\n ('Sales commission expense',     '6200', '620100', 'CC-SALES', NULL, 100, 'sample', 'system'),\n ('Commission payable',           '2300', '230100', NULL,       NULL, 100, 'sample', 'system'),\n ('Commission disbursement clearing', '1150', '113150', NULL,   NULL, 100, 'sample', 'system');\n" },
  { name: "0028_offer_behaviour_service_kinds.sql", sql: "-- Offer types get behaviour switches of their own (what an order creates, whether there are goods or a contract, where the offer is picked), and\n-- operators can define new kinds of service. A type's `template` is now the preset it started from; `behaviour` (null = the preset's own) is what it does.\nALTER TABLE offer_types ADD COLUMN behaviour jsonb;\n\n-- Kinds of service. The four built-ins are described here but their handling stays in the platform; a kind an operator adds (a roaming pass, a voucher,\n-- a prepaid top-up) is created by an order like any subscription, gets a generated identifier, may expire on its own, and is provisioned by instructions\n-- for the systems named here.\nCREATE TABLE service_kinds (\n  id                     text PRIMARY KEY CHECK (id ~ '^[A-Z][A-Z0-9_]{1,31}$'),\n  name                   text NOT NULL,\n  description            text,\n  is_builtin             boolean NOT NULL DEFAULT false,\n  status                 text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),\n  identifier_prefix      text NOT NULL DEFAULT 'SVC',          -- generated identifier: PREFIX + sequence\n  expires                boolean NOT NULL DEFAULT false,        -- the service ends by itself\n  validity_days          integer CHECK (validity_days IS NULL OR validity_days BETWEEN 1 AND 3650),  -- default length; an offer may set its own\n  provision_systems      jsonb NOT NULL DEFAULT '[]',           -- systems told when the service starts and ends, for example [\"PCRF\",\"VOUCHER_PLATFORM\"]\n  provision_instruction  text NOT NULL DEFAULT 'PROVISION',\n  deprovision_instruction text NOT NULL DEFAULT 'DEPROVISION',\n  sort_order             integer NOT NULL DEFAULT 100,\n  created_by             text,\n  created_at             timestamptz NOT NULL DEFAULT now(),\n  updated_at             timestamptz NOT NULL DEFAULT now()\n);\nINSERT INTO service_kinds (id, name, description, is_builtin, identifier_prefix, sort_order) VALUES\n  ('MOBILE',       'Mobile',        'A mobile line with a number and a SIM.',                    true, '+', 10),\n  ('FIBER',        'Fibre',         'Home fibre, set up by a technician visit.',                 true, 'FBR-', 20),\n  ('IOT',          'IoT',           'Connectivity for connected devices, often in bulk.',        true, 'IOT', 30),\n  ('SUBSCRIPTION', 'Subscription',  'An add-on or partner subscription billed with a plan.',     true, 'SUB-', 40);\n\n-- A service of an operator-defined kind is stored as a subscription, tagged with its kind, and may carry the date it ends.\nALTER TABLE services ADD COLUMN service_kind text, ADD COLUMN expires_at timestamptz;\nCREATE INDEX services_expiry_idx ON services (expires_at) WHERE expires_at IS NOT NULL AND status = 'ACTIVE';\n" },
  { name: "0029_ocs_jobs.sql", sql: "-- Provisioning into the online charging system (OCS). Whatever the vendor, Meridian queues what has to happen to a subscriber (create with a plan, change\n-- plan, bar or restore, change SIM or number, terminate) in the same transaction as the change, and a connector for the chosen vendor delivers it.\n-- Jobs for one service are delivered strictly in order and retried with a back-off; one that cannot be delivered is kept (DEAD) until someone retries it.\nCREATE TABLE ocs_jobs (\n  id               bigserial PRIMARY KEY,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now(),\n  service_id       uuid NOT NULL,\n  command          text NOT NULL CHECK (command IN ('PROVISION','CHANGE_PLAN','SET_BARRING','CHANGE_IDENTITY','TERMINATE')),\n  idempotency_key  text NOT NULL UNIQUE,\n  payload          jsonb NOT NULL,\n  status           text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','SKIPPED','DEAD')),\n  attempts         int NOT NULL DEFAULT 0,\n  next_attempt_at  timestamptz NOT NULL DEFAULT now(),\n  claimed_until    timestamptz,\n  vendor           text,\n  reference        text,\n  detail           text,\n  last_error       text,\n  sent_at          timestamptz\n);\nCREATE INDEX ocs_jobs_due_idx ON ocs_jobs (status, next_attempt_at) WHERE status = 'PENDING';\nCREATE INDEX ocs_jobs_service_idx ON ocs_jobs (service_id, id);\n" },
  { name: "0030_service_type_integration.sql", sql: "-- Service types (formerly service kinds) can all be adapted by the super user, built-in ones included: whether the network is told when a service of the\n-- type starts (built-in types have never done so, so it starts off for them), and whether services of the type are provisioned into the charging system.\nALTER TABLE service_kinds\n  ADD COLUMN announce_start boolean NOT NULL DEFAULT true,\n  ADD COLUMN ocs_enabled    boolean NOT NULL DEFAULT true;\nUPDATE service_kinds SET announce_start = false WHERE is_builtin;\n" },
  { name: "0031_data_migration.sql", sql: "-- Data migration: exports and imports are tracked as jobs, so progress, who ran what, the options used and the problems found can be seen afterwards.\n-- A job is one export (many entities, downloaded once) or one import (one entity, one uploaded file, checked and then loaded in slices).\nCREATE TABLE migration_jobs (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  kind             text NOT NULL CHECK (kind IN ('EXPORT','IMPORT')),\n  entity           text,                                   -- import: the entity being loaded\n  entities         text[] NOT NULL DEFAULT '{}',           -- export: what is in the archive\n  format           text NOT NULL CHECK (format IN ('CSV','JSON','NDJSON','XLSX')),\n  status           text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','VALIDATING','VALIDATED','IMPORTING','EXPORTING','COMPLETED','FAILED','CANCELLED','ROLLED_BACK')),\n  options          jsonb NOT NULL DEFAULT '{}',\n  masked           boolean NOT NULL DEFAULT true,          -- export: sensitive fields masked (false only for the super user, with a reason)\n  reason           text,\n  file_name        text,\n  file_bytes       bigint,\n  upload_id        uuid,\n  cursor_bytes     bigint NOT NULL DEFAULT 0,              -- import: how far into the file the current pass has got (always the start of a row)\n  rows_total       bigint,\n  rows_done        bigint NOT NULL DEFAULT 0,\n  rows_ok          bigint NOT NULL DEFAULT 0,\n  rows_error       bigint NOT NULL DEFAULT 0,\n  rows_skipped     bigint NOT NULL DEFAULT 0,\n  percent          smallint NOT NULL DEFAULT 0 CHECK (percent BETWEEN 0 AND 100),\n  stage            text,\n  summary          jsonb NOT NULL DEFAULT '{}',\n  template_version text,\n  claimed_until    timestamptz,\n  created_by       text NOT NULL,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  started_at       timestamptz,\n  finished_at      timestamptz,\n  updated_at       timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX migration_jobs_recent_idx ON migration_jobs (created_at DESC);\nCREATE INDEX migration_jobs_active_idx ON migration_jobs (status) WHERE status IN ('PENDING','VALIDATING','IMPORTING','EXPORTING');\n\n-- Row-level problems and warnings found while checking or loading an import. Capped per job by the application.\nCREATE TABLE migration_job_items (\n  id        bigserial PRIMARY KEY,\n  job_id    uuid NOT NULL REFERENCES migration_jobs (id) ON DELETE CASCADE,\n  line      bigint NOT NULL,\n  severity  text NOT NULL CHECK (severity IN ('ERROR','WARNING')),\n  field     text,\n  code      text NOT NULL,\n  message   text NOT NULL,\n  pass      text NOT NULL DEFAULT 'VALIDATE'\n);\nCREATE INDEX migration_job_items_job_idx ON migration_job_items (job_id, id);\n\n-- The template of each entity as it was when last published: its version changes whenever a column does, so a file made from an old template is recognised.\nCREATE TABLE data_templates (\n  entity      text PRIMARY KEY,\n  version     text NOT NULL,\n  label       text NOT NULL,\n  domain      text NOT NULL,\n  phase       smallint NOT NULL,\n  importable  boolean NOT NULL,\n  columns     jsonb NOT NULL,\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\n" },
  { name: "0032_data_migration_import.sql", sql: "-- Importing: uploaded files wait here, in pieces, until a job has read them; and every record a job creates is remembered against the key it had in the old system.\nCREATE TABLE migration_uploads (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  created_by    text NOT NULL,\n  file_name     text NOT NULL,\n  total_bytes   bigint NOT NULL,\n  chunk_bytes   integer NOT NULL,\n  chunks        integer NOT NULL,\n  storage       text NOT NULL DEFAULT 'DB' CHECK (storage IN ('DB','S3')),\n  object_key    text,\n  format        text CHECK (format IN ('CSV','NDJSON')),     -- what the job reads, after a JSON document or a spreadsheet has been turned into rows\n  rows_hint     bigint,\n  sha256        text,\n  status        text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','COMPLETE','DISCARDED')),\n  note          jsonb NOT NULL DEFAULT '{}',\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  completed_at  timestamptz\n);\nCREATE TABLE migration_blobs (\n  upload_id  uuid NOT NULL REFERENCES migration_uploads (id) ON DELETE CASCADE,\n  seq        integer NOT NULL,\n  data       bytea NOT NULL,\n  PRIMARY KEY (upload_id, seq)\n);\n\n-- The key a record had in the old system -> the id Meridian gave it. This lets other files point at records by their old key, makes loading the same file twice safe\n-- (a key that is already here is skipped, not duplicated), and lets a job's own records be taken out again.\nCREATE TABLE migration_refs (\n  entity       text NOT NULL,\n  ref          text NOT NULL,\n  internal_id  text NOT NULL,\n  job_id       uuid,\n  created      boolean NOT NULL DEFAULT true,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (entity, ref)\n);\nCREATE INDEX migration_refs_job_idx ON migration_refs (job_id) WHERE job_id IS NOT NULL;\n\n-- Keys seen so far in the file being checked, so a row can point at a record that appears earlier in the same file.\nCREATE TABLE migration_keys (\n  job_id  uuid NOT NULL REFERENCES migration_jobs (id) ON DELETE CASCADE,\n  key     text NOT NULL,\n  PRIMARY KEY (job_id, key)\n);\n\n-- Opening balances are invoices of this kind.\nALTER TABLE invoices DROP CONSTRAINT IF EXISTS invoices_kind_check;\nALTER TABLE invoices ADD CONSTRAINT invoices_kind_check CHECK (kind IN ('CYCLE','FINAL','ADJUSTMENT','OPENING'));\n\n-- Taking a load out again runs in slices too, so it has a status of its own.\nALTER TABLE migration_jobs DROP CONSTRAINT IF EXISTS migration_jobs_status_check;\nALTER TABLE migration_jobs ADD CONSTRAINT migration_jobs_status_check CHECK (status IN ('PENDING','VALIDATING','VALIDATED','IMPORTING','EXPORTING','COMPLETED','FAILED','CANCELLED','ROLLING_BACK','ROLLED_BACK'));\nDROP INDEX IF EXISTS migration_jobs_active_idx;\nCREATE INDEX migration_jobs_active_idx ON migration_jobs (status) WHERE status IN ('PENDING','VALIDATING','IMPORTING','EXPORTING','ROLLING_BACK');\n" },
  { name: "0033_lookup_indexes.sql", sql: "-- Found by the scale benchmark (packages/core/bench, 4 million customers, 4.8 million services, 3 million orders on Postgres 16).\n-- A row of a sharded table is found by (shard_id, id), but much of the code finds it by id alone, and the primary key cannot serve that: Postgres read every\n-- partition's table or index, 150-400 ms. A plain index on id makes it one probe per partition, under a millisecond. (A unique index on id alone is not allowed\n-- on a table partitioned by shard_id, so these are ordinary indexes; the primary key still enforces uniqueness.)\nCREATE INDEX IF NOT EXISTS customers_id_idx ON customers (id);\nCREATE INDEX IF NOT EXISTS accounts_id_idx ON accounts (id);\nCREATE INDEX IF NOT EXISTS orders_id_idx ON orders (id);\nCREATE INDEX IF NOT EXISTS services_id_idx ON services (id);\n-- What an order made (its lines, its services) is found by the order's id.\nCREATE INDEX IF NOT EXISTS order_lines_order_id_idx ON order_lines (order_id);\nCREATE INDEX IF NOT EXISTS services_order_idx ON services (order_id) WHERE order_id IS NOT NULL;\n-- A bill run takes the accounts of one cycle day a page at a time in id order: with the id in the index each partition hands its rows over already sorted.\nCREATE INDEX IF NOT EXISTS accounts_cycle_page_idx ON accounts (bill_cycle_day, id) WHERE status = 'ACTIVE';\nDROP INDEX IF EXISTS accounts_cycle_idx;\n\n-- Order numbers without a lock held for the whole order. The counter row of the day used to be updated at the start of every order and stayed locked until the\n-- order committed, so orders queued behind each other: about 10 orders a second however many servers were taking them. Now each order takes the next value of a\n-- sequence (which never waits) and the number is that value less the day's starting point, so numbers are still 1, 2, 3 … each day. The one change: an order that\n-- fails after taking a number leaves a gap, as with any sequence.\nCREATE SEQUENCE IF NOT EXISTS order_number_seq;\nALTER TABLE order_counters ADD COLUMN IF NOT EXISTS base bigint NOT NULL DEFAULT 0;\n-- Days already counted keep their numbers; the sequence starts above every counter so nothing repeats.\nSELECT setval('order_number_seq', GREATEST((SELECT COALESCE(max(last), 0) FROM order_counters), 1));\n" },
  { name: "0034_bill_runs.sql", sql: "-- Governed bill runs: every cycle is billed in four stages (mock, review, approval, production), and the mock is kept so what was approved is what is billed.\n\n-- One row per monthly cycle day, so each of the 28 cycles can be switched off, given its own label and its own approval rule.\nCREATE TABLE bill_cycle_configs (\n  cycle_day    smallint PRIMARY KEY CHECK (cycle_day BETWEEN 1 AND 28),\n  label        text NOT NULL DEFAULT '',\n  enabled      boolean NOT NULL DEFAULT true,\n  dual_control boolean,                       -- null: follow the global setting; true/false: this cycle always/never needs a second person\n  notes        text NOT NULL DEFAULT '',\n  updated_by   text,\n  updated_at   timestamptz NOT NULL DEFAULT now()\n);\nINSERT INTO bill_cycle_configs (cycle_day, label) SELECT d, 'Cycle ' || d FROM generate_series(1, 28) d;\n\nCREATE TABLE bill_runs (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  kind              text NOT NULL CHECK (kind IN ('CYCLE','DAILY','SELECTIVE')),   -- a cycle day, the daily-cycle accounts, or only the accounts chosen\n  cycle_day         smallint,\n  as_of             date NOT NULL,                     -- the bill date: the period billed is the one ending the day before\n  status            text NOT NULL CHECK (status IN ('MOCK_RUNNING','MOCK_COMPLETED','PENDING_APPROVAL','APPROVED','PRODUCTION_RUNNING','COMPLETED','FAILED','CANCELLED')),\n  options           jsonb NOT NULL DEFAULT '{}',\n  note              text,\n  requested_by      text NOT NULL,\n  submitted_by      text,\n  submitted_at      timestamptz,\n  approved_by       text,\n  approved_at       timestamptz,\n  approval_note     text,\n  mock_finished_at  timestamptz,\n  started_at        timestamptz,\n  finished_at       timestamptz,\n  accounts_total    integer NOT NULL DEFAULT 0,\n  mock_net_minor    bigint NOT NULL DEFAULT 0,\n  mock_tax_minor    bigint NOT NULL DEFAULT 0,\n  mock_total_minor  bigint NOT NULL DEFAULT 0,\n  billed_invoices   integer NOT NULL DEFAULT 0,\n  billed_total_minor bigint NOT NULL DEFAULT 0,\n  summary           jsonb NOT NULL DEFAULT '{}',       -- revenue by stream, tax by market, counts by problem\n  stage             text,\n  percent           smallint NOT NULL DEFAULT 0 CHECK (percent BETWEEN 0 AND 100),\n  claimed_until     timestamptz,\n  workflow_id       text,                              -- the Temporal workflow driving this run, when one is\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX bill_runs_recent_idx ON bill_runs (created_at DESC);\nCREATE INDEX bill_runs_active_idx ON bill_runs (status) WHERE status IN ('MOCK_RUNNING','PRODUCTION_RUNNING');\nCREATE INDEX bill_runs_cycle_idx ON bill_runs (cycle_day, as_of DESC);\n\n-- Every account in a run, with what the mock found and what the production run did. Also the work queue: both passes walk it in account order.\nCREATE TABLE bill_run_items (\n  run_id            uuid NOT NULL REFERENCES bill_runs (id) ON DELETE CASCADE,\n  account_id        uuid NOT NULL,\n  customer_id       uuid NOT NULL,\n  status            text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','MOCKED','NO_INVOICE','EXCLUDED','BILLED','FAILED','SKIPPED')),\n  period_start      date,\n  period_end        date,\n  net_minor         bigint NOT NULL DEFAULT 0,\n  tax_minor         bigint NOT NULL DEFAULT 0,\n  total_minor       bigint NOT NULL DEFAULT 0,\n  line_count        integer NOT NULL DEFAULT 0,\n  prev_total_minor  bigint,                            -- the account's previous cycle invoice, for the comparison\n  anomalies         text[] NOT NULL DEFAULT '{}',\n  excluded_reason   text,\n  exclusion_id      bigint,                            -- which exclusion kept it out, so lifting that exclusion brings it back\n  invoice_id        uuid,\n  billed_total_minor bigint,\n  error             text,\n  PRIMARY KEY (run_id, account_id)\n);\nCREATE INDEX bill_run_items_work_idx ON bill_run_items (run_id, status, account_id);\nCREATE INDEX bill_run_items_anomaly_idx ON bill_run_items (run_id, account_id) WHERE cardinality(anomalies) > 0;\nCREATE INDEX bill_run_items_customer_idx ON bill_run_items (run_id, customer_id);\n\n-- Accounts (or a whole enterprise customer with every department below it) kept out of a bill run: a legal dispute, a fraud investigation.\n-- run_id empty: a standing exclusion that applies to every run until it is lifted or reaches its end date.\nCREATE TABLE bill_run_exclusions (\n  id          bigserial PRIMARY KEY,\n  scope       text NOT NULL CHECK (scope IN ('ACCOUNT','CUSTOMER_NODE')),\n  account_id  uuid,\n  customer_id uuid,\n  run_id      uuid REFERENCES bill_runs (id) ON DELETE CASCADE,\n  reason      text NOT NULL,\n  until_date  date,\n  created_by  text NOT NULL,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  removed_by  text,\n  removed_at  timestamptz,\n  CHECK ((scope = 'ACCOUNT' AND account_id IS NOT NULL) OR (scope = 'CUSTOMER_NODE' AND customer_id IS NOT NULL))\n);\nCREATE INDEX bill_run_exclusions_active_idx ON bill_run_exclusions (run_id) WHERE removed_at IS NULL;\n\nALTER TABLE invoices ADD COLUMN IF NOT EXISTS bill_run_id uuid;\nCREATE INDEX IF NOT EXISTS invoices_bill_run_idx ON invoices (bill_run_id) WHERE bill_run_id IS NOT NULL;\n-- Accounts on the daily cycle, in id order, for the daily run's keyset walk.\nCREATE INDEX IF NOT EXISTS accounts_daily_idx ON accounts (id) WHERE bill_cycle_day IS NULL AND status = 'ACTIVE';\n" },
  { name: "0035_billing_simulation.sql", sql: "-- Simulations: forward projections, early-termination quotes and plan-change what-ifs are computed without touching real billing, and can be saved\n-- (a quote an agent gave a customer, a forecast Finance wants to keep). Nothing here is read by billing, the ledger or reports.\nCREATE TABLE simulation_runs (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  kind        text NOT NULL CHECK (kind IN ('PROJECTION','TERMINATION','PLAN_CHANGE')),\n  title       text NOT NULL DEFAULT '',\n  account_id  uuid,\n  service_id  uuid,\n  cycle_day   smallint NOT NULL DEFAULT 0,          -- the account's bill cycle day, 0 for a daily cycle\n  params      jsonb NOT NULL DEFAULT '{}',\n  summary     jsonb NOT NULL DEFAULT '{}',\n  created_by  text NOT NULL,\n  created_at  timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX simulation_runs_recent_idx ON simulation_runs (created_at DESC);\nCREATE INDEX simulation_runs_account_idx ON simulation_runs (account_id, created_at DESC) WHERE account_id IS NOT NULL;\n\n-- One row per simulated bill (or settlement), partitioned by the account's bill cycle day so a cycle's simulations live together and can be dropped together.\nCREATE TABLE simulation_ledger (\n  cycle_day    smallint NOT NULL,\n  run_id       uuid NOT NULL REFERENCES simulation_runs (id) ON DELETE CASCADE,\n  seq          integer NOT NULL,\n  kind         text NOT NULL CHECK (kind IN ('BILL','SETTLEMENT','PLAN_CHANGE')),\n  bill_date    date NOT NULL,\n  period_start date,\n  period_end   date,\n  net_minor    bigint NOT NULL,\n  tax_minor    bigint NOT NULL,\n  total_minor  bigint NOT NULL,\n  balance_minor bigint,                              -- the device balance still to pay after this bill\n  lines        jsonb NOT NULL DEFAULT '[]',\n  PRIMARY KEY (cycle_day, run_id, seq)\n) PARTITION BY LIST (cycle_day);\nDO $$\nBEGIN\n  FOR d IN 0..28 LOOP\n    EXECUTE format('CREATE TABLE simulation_ledger_c%s PARTITION OF simulation_ledger FOR VALUES IN (%s)', lpad(d::text, 2, '0'), d);\n  END LOOP;\nEND $$;\nCREATE INDEX simulation_ledger_run_idx ON simulation_ledger (run_id, seq);\n" },
  { name: "0036_bill_templates.sql", sql: "-- Bill templates: the layout of a customer's bill, designed on screen or converted from a legacy format. A template is edited as a draft and published as a\n-- numbered version; issued bills are always drawn with a published version, so changing a draft never changes a bill already sent.\nCREATE TABLE bill_templates (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name          text NOT NULL,\n  description   text NOT NULL DEFAULT '',\n  source        text NOT NULL DEFAULT 'DESIGNER' CHECK (source IN ('DESIGNER','LEGACY_HTML','LEGACY_JSON','LEGACY_XML')),\n  draft         jsonb NOT NULL,                       -- the TemplateSchema being edited\n  report        jsonb,                                -- what a legacy conversion carried over, warned about, or dropped\n  version       integer NOT NULL DEFAULT 0,           -- the latest published version, 0 when never published\n  is_default    boolean NOT NULL DEFAULT false,       -- the template used when none is named; always a published one\n  created_by    text NOT NULL,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_by    text NOT NULL,\n  updated_at    timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX bill_templates_default_uq ON bill_templates (is_default) WHERE is_default;\n\nCREATE TABLE bill_template_versions (\n  template_id   uuid NOT NULL REFERENCES bill_templates (id) ON DELETE CASCADE,\n  version       integer NOT NULL,\n  schema        jsonb NOT NULL,\n  note          text NOT NULL DEFAULT '',\n  published_by  text NOT NULL,\n  published_at  timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (template_id, version)\n);\n\n-- A print-house job: which bills went out, drawn with which template version and print profile, and the manifest the printer receives.\nCREATE TABLE print_jobs (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  bill_run_id      uuid,\n  template_id      uuid NOT NULL REFERENCES bill_templates (id),\n  template_version integer NOT NULL,\n  profile          jsonb NOT NULL,\n  selection        jsonb NOT NULL DEFAULT '{}',\n  status           text NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING','COMPLETED','FAILED')),\n  invoice_count    integer NOT NULL DEFAULT 0,\n  page_count       integer NOT NULL DEFAULT 0,\n  summary          jsonb NOT NULL DEFAULT '{}',\n  created_by       text NOT NULL,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  finished_at      timestamptz\n);\nCREATE INDEX print_jobs_recent_idx ON print_jobs (created_at DESC);\n" },
  { name: "0037_case_management.sql", sql: "-- Case management: a three-level taxonomy (category → sub-category → issue type), an SLA matrix by customer tier and severity, the full telecom case lifecycle,\n-- the interaction registry (every customer touchpoint, bound to a case or not), and a per-case audit trail of status changes.\n\nCREATE TABLE case_taxonomy (\n  id               text PRIMARY KEY,\n  parent_id        text REFERENCES case_taxonomy (id),\n  level            smallint NOT NULL CHECK (level BETWEEN 1 AND 3),    -- 1 category, 2 sub-category, 3 issue type\n  name             text NOT NULL,\n  description      text,\n  active           boolean NOT NULL DEFAULT true,\n  sort_order       integer NOT NULL DEFAULT 0,\n  -- Only on an issue type (level 3): what a case of this kind is.\n  case_type        text CHECK (case_type IN ('FIBER_ASSURANCE','BILLING_REFUND','MNP_PORT_OUT','GENERAL')),\n  default_severity text CHECK (default_severity IN ('CRITICAL_OUTAGE','MAJOR_DEGRADATION','MINOR_INQUIRY')),\n  needs_dispatch   boolean NOT NULL DEFAULT false,                     -- a visit by a technician is the usual fix\n  skills           text[] NOT NULL DEFAULT '{}',                       -- what the technician must hold, e.g. FIBER_SPLICING\n  equipment        text[] NOT NULL DEFAULT '{}',                       -- what to reserve, e.g. ONT_UNIT\n  CHECK ((level = 1) = (parent_id IS NULL))\n);\nCREATE INDEX case_taxonomy_parent_idx ON case_taxonomy (parent_id, sort_order);\n\nCREATE TABLE case_sla_config (\n  tier                  text NOT NULL CHECK (tier IN ('VIP','ENTERPRISE','STANDARD')),\n  severity              text NOT NULL CHECK (severity IN ('CRITICAL_OUTAGE','MAJOR_DEGRADATION','MINOR_INQUIRY')),\n  first_response_minutes integer NOT NULL CHECK (first_response_minutes > 0),\n  resolution_minutes    integer NOT NULL CHECK (resolution_minutes > 0),\n  warn_percent          smallint NOT NULL DEFAULT 80 CHECK (warn_percent BETWEEN 1 AND 99),\n  updated_by            text,\n  updated_at            timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tier, severity),\n  CHECK (first_response_minutes <= resolution_minutes)\n);\nINSERT INTO case_sla_config (tier, severity, first_response_minutes, resolution_minutes) VALUES\n  ('VIP','CRITICAL_OUTAGE',15,240), ('VIP','MAJOR_DEGRADATION',30,720), ('VIP','MINOR_INQUIRY',120,2880),\n  ('ENTERPRISE','CRITICAL_OUTAGE',30,480), ('ENTERPRISE','MAJOR_DEGRADATION',60,1440), ('ENTERPRISE','MINOR_INQUIRY',240,4320),\n  ('STANDARD','CRITICAL_OUTAGE',60,720), ('STANDARD','MAJOR_DEGRADATION',240,2880), ('STANDARD','MINOR_INQUIRY',480,7200);\n\nINSERT INTO case_taxonomy (id, parent_id, level, name, sort_order, case_type, default_severity, needs_dispatch, skills, equipment) VALUES\n  ('broadband',            NULL,        1, 'Broadband / Fiber', 10, NULL, NULL, false, '{}', '{}'),\n  ('mobile',               NULL,        1, 'Mobile',            20, NULL, NULL, false, '{}', '{}'),\n  ('billing',              NULL,        1, 'Billing',           30, NULL, NULL, false, '{}', '{}'),\n  ('porting',              NULL,        1, 'Number porting',    40, NULL, NULL, false, '{}', '{}'),\n  ('general',              NULL,        1, 'General',           50, NULL, NULL, false, '{}', '{}'),\n  ('broadband.down',       'broadband', 2, 'No signal / down',  10, NULL, NULL, false, '{}', '{}'),\n  ('broadband.slow',       'broadband', 2, 'Slow or intermittent', 20, NULL, NULL, false, '{}', '{}'),\n  ('broadband.other',      'broadband', 2, 'Other',             90, NULL, NULL, false, '{}', '{}'),\n  ('mobile.nosvc',         'mobile',    2, 'No service or data', 10, NULL, NULL, false, '{}', '{}'),\n  ('billing.dispute',      'billing',   2, 'Bill dispute',      10, NULL, NULL, false, '{}', '{}'),\n  ('billing.other',        'billing',   2, 'Other',             90, NULL, NULL, false, '{}', '{}'),\n  ('porting.out',          'porting',   2, 'Port-out',          10, NULL, NULL, false, '{}', '{}'),\n  ('general.enquiry',      'general',   2, 'Enquiry',           10, NULL, NULL, false, '{}', '{}'),\n  ('broadband.down.los',   'broadband.down', 3, 'LOS red light on',          10, 'FIBER_ASSURANCE', 'CRITICAL_OUTAGE',   true,  '{FIBER_SPLICING}', '{ONT_UNIT}'),\n  ('broadband.down.cut',   'broadband.down', 3, 'Fibre cable cut or damaged', 20, 'FIBER_ASSURANCE', 'CRITICAL_OUTAGE',   true,  '{FIBER_SPLICING}', '{FIBER_DROP_CABLE}'),\n  ('broadband.down.ont',   'broadband.down', 3, 'ONT not powering on',        30, 'FIBER_ASSURANCE', 'MAJOR_DEGRADATION', true,  '{ONT_INSTALL}', '{ONT_UNIT}'),\n  ('broadband.slow.drops', 'broadband.slow', 3, 'Connection drops',           10, 'FIBER_ASSURANCE', 'MAJOR_DEGRADATION', false, '{}', '{}'),\n  ('broadband.slow.speed', 'broadband.slow', 3, 'Below plan speed',           20, 'FIBER_ASSURANCE', 'MINOR_INQUIRY',     false, '{}', '{}'),\n  ('broadband.other.any',  'broadband.other', 3, 'Other fibre problem',       10, 'FIBER_ASSURANCE', 'MINOR_INQUIRY',     false, '{}', '{}'),\n  ('mobile.nosvc.nosignal','mobile.nosvc',   3, 'No signal',                  10, 'GENERAL',         'MAJOR_DEGRADATION', false, '{}', '{}'),\n  ('mobile.nosvc.data',    'mobile.nosvc',   3, 'Data not working',           20, 'GENERAL',         'MAJOR_DEGRADATION', false, '{}', '{}'),\n  ('billing.dispute.dup',  'billing.dispute', 3, 'Duplicate charge',          10, 'BILLING_REFUND',  'MINOR_INQUIRY',     false, '{}', '{}'),\n  ('billing.dispute.amt',  'billing.dispute', 3, 'Wrong amount',              20, 'BILLING_REFUND',  'MINOR_INQUIRY',     false, '{}', '{}'),\n  ('billing.other.any',    'billing.other',  3, 'Other billing question',     10, 'BILLING_REFUND',  'MINOR_INQUIRY',     false, '{}', '{}'),\n  ('porting.out.request',  'porting.out',    3, 'Port-out request',           10, 'MNP_PORT_OUT',    'MINOR_INQUIRY',     false, '{}', '{}'),\n  ('general.enquiry.any',  'general.enquiry', 3, 'General enquiry',           10, 'GENERAL',         'MINOR_INQUIRY',     false, '{}', '{}');\n\n-- Cases: the lifecycle, the taxonomy path, the SLA clocks and who works it.\nALTER TABLE cases DROP CONSTRAINT IF EXISTS cases_status_check;\nUPDATE cases SET status = 'NEW' WHERE status = 'OPEN';\nUPDATE cases SET status = 'CLOSED_VERIFIED' WHERE status = 'CLOSED';\nALTER TABLE cases ADD CONSTRAINT cases_status_check CHECK (status IN ('NEW','IN_PROGRESS','PENDING_CUSTOMER','PENDING_THIRD_PARTY','PENDING_DISPATCH','DISPATCHED','RESOLVED','CLOSED_AUTO','CLOSED_VERIFIED','REOPENED'));\nALTER TABLE cases ALTER COLUMN status SET DEFAULT 'NEW';\nALTER TABLE cases\n  ADD COLUMN issue_type_id         text REFERENCES case_taxonomy (id),\n  ADD COLUMN category_path         text,\n  ADD COLUMN severity              text NOT NULL DEFAULT 'MINOR_INQUIRY' CHECK (severity IN ('CRITICAL_OUTAGE','MAJOR_DEGRADATION','MINOR_INQUIRY')),\n  ADD COLUMN tier                  text NOT NULL DEFAULT 'STANDARD' CHECK (tier IN ('VIP','ENTERPRISE','STANDARD')),\n  ADD COLUMN assignee              text,\n  ADD COLUMN team                  text,\n  ADD COLUMN channel               text,\n  ADD COLUMN postal_node           text,\n  ADD COLUMN master_case_id        uuid REFERENCES cases (id),\n  ADD COLUMN sla_first_response_minutes integer,\n  ADD COLUMN sla_resolution_minutes     integer,\n  ADD COLUMN sla_warn_percent      smallint NOT NULL DEFAULT 80,\n  ADD COLUMN first_response_due    timestamptz,\n  ADD COLUMN first_response_at     timestamptz,\n  ADD COLUMN resolution_due        timestamptz,\n  ADD COLUMN sla_paused_at         timestamptz,\n  ADD COLUMN sla_warned_at         timestamptz,\n  ADD COLUMN sla_breached_at       timestamptz,\n  ADD COLUMN resolved_at           timestamptz,\n  ADD COLUMN closed_at             timestamptz,\n  ADD COLUMN resolution            text,\n  ADD COLUMN auto_close_at         timestamptz,                        -- a resolved case closes itself at this time unless the customer reopens it\n  ADD COLUMN reopen_count          integer NOT NULL DEFAULT 0;\nUPDATE cases SET issue_type_id = CASE type WHEN 'FIBER_ASSURANCE' THEN 'broadband.other.any' WHEN 'BILLING_REFUND' THEN 'billing.other.any' WHEN 'MNP_PORT_OUT' THEN 'porting.out.request' ELSE 'general.enquiry.any' END,\n  priority = priority;\nUPDATE cases SET severity = CASE priority WHEN 'URGENT' THEN 'CRITICAL_OUTAGE' WHEN 'HIGH' THEN 'MAJOR_DEGRADATION' ELSE 'MINOR_INQUIRY' END;\nUPDATE cases SET resolved_at = updated_at WHERE status IN ('RESOLVED','CLOSED_VERIFIED');\nUPDATE cases SET closed_at = updated_at WHERE status = 'CLOSED_VERIFIED';\n\nDROP INDEX IF EXISTS cases_open_idx;\nCREATE INDEX cases_active_idx ON cases (created_at DESC) WHERE status NOT IN ('RESOLVED','CLOSED_AUTO','CLOSED_VERIFIED');\nCREATE INDEX cases_assignee_idx ON cases (assignee, status) WHERE assignee IS NOT NULL;\nCREATE INDEX cases_resolution_due_idx ON cases (resolution_due) WHERE status NOT IN ('RESOLVED','CLOSED_AUTO','CLOSED_VERIFIED') AND sla_paused_at IS NULL;\nCREATE INDEX cases_master_idx ON cases (master_case_id) WHERE master_case_id IS NOT NULL;\nCREATE INDEX cases_node_idx ON cases (postal_node, status) WHERE postal_node IS NOT NULL;\nCREATE INDEX cases_auto_close_idx ON cases (auto_close_at) WHERE auto_close_at IS NOT NULL;\n\n-- Every touchpoint with a customer, on any channel, whether or not it became (or belongs to) a case.\nCREATE TABLE customer_interactions (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  customer_id  uuid NOT NULL,\n  case_id      uuid REFERENCES cases (id),\n  service_id   uuid,\n  channel      text NOT NULL CHECK (channel IN ('CALL_CENTER','RETAIL_POS','WHATSAPP','WEB_SELF_SERVE','MOBILE_APP','EMAIL','IN_STORE')),\n  direction    text NOT NULL CHECK (direction IN ('INBOUND','OUTBOUND')),\n  subject      text NOT NULL,\n  summary      text NOT NULL DEFAULT '',\n  agent        text,                                                   -- the staff member, when there is one\n  session_ref  text,                                                   -- the call id, chat session or ticket id on the channel's own system\n  duration_sec integer CHECK (duration_sec IS NULL OR duration_sec >= 0),\n  occurred_at  timestamptz NOT NULL DEFAULT now(),\n  metadata     jsonb NOT NULL DEFAULT '{}',\n  created_by   text NOT NULL,\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX customer_interactions_customer_idx ON customer_interactions (customer_id, occurred_at DESC, id DESC);\nCREATE INDEX customer_interactions_case_idx ON customer_interactions (case_id, occurred_at) WHERE case_id IS NOT NULL;\nCREATE UNIQUE INDEX customer_interactions_session_uq ON customer_interactions (channel, session_ref) WHERE session_ref IS NOT NULL;\n\n-- What happened to a case and when: every status change, assignment and SLA event.\nCREATE TABLE case_audit_log (\n  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  case_id     uuid NOT NULL REFERENCES cases (id),\n  at          timestamptz NOT NULL DEFAULT now(),\n  actor       text NOT NULL,\n  action      text NOT NULL,                                           -- CREATED, STATUS, ASSIGNED, SEVERITY, NOTE, INTERACTION, SLA_WARNING, SLA_BREACH ...\n  from_status text,\n  to_status   text,\n  detail      jsonb NOT NULL DEFAULT '{}'\n);\nCREATE INDEX case_audit_log_case_idx ON case_audit_log (case_id, id);\n\n-- A VIP customer gets the VIP row of the SLA matrix; Enterprise-segment customers get the Enterprise row; everyone else Standard.\nALTER TABLE customers ADD COLUMN IF NOT EXISTS vip boolean NOT NULL DEFAULT false;\n" },
  { name: "0038_case_sla_refunds_incidents.sql", sql: "-- Case SLA watchdog, refund approvals by amount, and master network incidents.\n\nALTER TABLE cases\n  ALTER COLUMN customer_id DROP NOT NULL,                              -- a master incident belongs to the network, not to a customer\n  ADD COLUMN is_master                    boolean NOT NULL DEFAULT false,\n  ADD COLUMN escalation_level             smallint NOT NULL DEFAULT 0, -- 0 none, 1 after the SLA is breached, 2 when it is half as late again\n  ADD COLUMN first_response_breached_at   timestamptz;\nCREATE SEQUENCE IF NOT EXISTS incident_seq START 1;\nCREATE INDEX cases_master_open_idx ON cases (postal_node) WHERE is_master AND status NOT IN ('RESOLVED','CLOSED_AUTO','CLOSED_VERIFIED');\n\n-- A refund or credit asked for on a billing-dispute case. Above what the asker may approve themselves it waits for someone in a higher tier.\nCREATE TABLE case_refund_requests (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  case_id       uuid NOT NULL REFERENCES cases (id),\n  invoice_id    uuid NOT NULL,\n  amount_minor  bigint NOT NULL CHECK (amount_minor > 0),\n  currency      char(3) NOT NULL,\n  reason        text NOT NULL,\n  status        text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','EXECUTED','REJECTED','CANCELLED')),\n  required_tier smallint NOT NULL,                                     -- the lowest tier (0 first) whose limit covers the amount\n  requested_by  text NOT NULL,\n  requested_at  timestamptz NOT NULL DEFAULT now(),\n  decided_by    text,\n  decided_at    timestamptz,\n  decision_note text,\n  CHECK (status = 'PENDING' OR decided_at IS NOT NULL)\n);\nCREATE INDEX case_refund_case_idx ON case_refund_requests (case_id, requested_at DESC);\nCREATE INDEX case_refund_pending_idx ON case_refund_requests (requested_at) WHERE status = 'PENDING';\n" },
  { name: "0039_workforce_dispatch.sql", sql: "-- Field service: technician visits booked in an external workforce-management (WFM) system for a case, and the log of what that system tells us.\n\nCREATE TABLE workforce_appointments (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  case_id          uuid NOT NULL REFERENCES cases (id),\n  customer_id      uuid,\n  vendor           text NOT NULL,                                       -- which WFM connector made the booking\n  status           text NOT NULL DEFAULT 'RESERVED' CHECK (status IN\n                     ('RESERVED','REQUESTED','SCHEDULED','ASSIGNED','EN_ROUTE','ON_SITE','COMPLETED','NO_ACCESS','RESCHEDULE_REQUIRED','CANCELLED','EXPIRED')),\n  slot_start       timestamptz NOT NULL,\n  slot_end         timestamptz NOT NULL,\n  skills           text[] NOT NULL DEFAULT '{}',                        -- what the technician must hold\n  equipment        text[] NOT NULL DEFAULT '{}',                        -- what is reserved for the visit\n  address          jsonb NOT NULL DEFAULT '{}',\n  reservation_ref  text,                                                -- the WFM's hold on the slot\n  external_ref     text,                                                -- the WFM's job (work order) id\n  technician_ref   text,\n  technician_name  text,\n  technician_phone text,\n  notes            text NOT NULL DEFAULT '',\n  outcome_note     text,\n  hold_expires_at  timestamptz,                                         -- a reserved slot not confirmed by then is released\n  last_event_rank  smallint NOT NULL DEFAULT 0,                         -- how far the visit has got, so a late or repeated callback cannot move it back\n  last_event_at    timestamptz,\n  created_by       text NOT NULL,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now(),\n  CHECK (slot_end > slot_start)\n);\nCREATE INDEX workforce_appointments_case_idx ON workforce_appointments (case_id, created_at DESC);\nCREATE UNIQUE INDEX workforce_appointments_job_uq ON workforce_appointments (vendor, external_ref) WHERE external_ref IS NOT NULL;\nCREATE INDEX workforce_appointments_open_idx ON workforce_appointments (slot_start) WHERE status IN ('RESERVED','REQUESTED','SCHEDULED','ASSIGNED','EN_ROUTE','ON_SITE');\n\n-- Everything the WFM system sends to the callback URL, once per event id: so a repeated delivery changes nothing and what was done about each event can be seen.\nCREATE TABLE webhook_event_log (\n  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  source        text NOT NULL,\n  event_id      text NOT NULL,\n  event_type    text NOT NULL,\n  external_ref  text,\n  case_id       uuid,\n  status        text NOT NULL DEFAULT 'RECEIVED' CHECK (status IN ('RECEIVED','APPLIED','IGNORED','FAILED','UNKNOWN_JOB')),\n  detail        text,\n  payload       jsonb NOT NULL,\n  received_at   timestamptz NOT NULL DEFAULT now(),\n  processed_at  timestamptz,\n  UNIQUE (source, event_id)\n);\nCREATE INDEX webhook_event_log_job_idx ON webhook_event_log (source, external_ref, id);\nCREATE INDEX webhook_event_log_case_idx ON webhook_event_log (case_id, id) WHERE case_id IS NOT NULL;\n\n-- A visit that does not happen when it should is something to chase: the time to look at it, and whether supervisors were told.\nALTER TABLE cases\n  ADD COLUMN dispatch_due_at      timestamptz,\n  ADD COLUMN dispatch_notified_at timestamptz;\n" },
  { name: "0040_dunning_rules.sql", sql: "-- Rule-based dunning: strategies by kind of customer, each a ladder of steps with its own trigger, action and exclusions; late-fee settings; payment arrangements;\n-- accounts handed to a collection agency. Where no rule exists the single ladder in Settings → Lifecycle keeps working as before.\n\nALTER TABLE customers ADD COLUMN IF NOT EXISTS credit_risk text NOT NULL DEFAULT 'NORMAL' CHECK (credit_risk IN ('NORMAL','HIGH'));   -- a history of bad credit\n\nCREATE TABLE late_fee_configs (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  code           text NOT NULL UNIQUE,\n  name           text NOT NULL,\n  mode           text NOT NULL CHECK (mode IN ('FLAT','PERCENT')),         -- a fixed charge, or a percentage of the overdue balance (a month's interest)\n  flat_minor     bigint NOT NULL DEFAULT 0 CHECK (flat_minor >= 0),\n  percent_bps    integer NOT NULL DEFAULT 0 CHECK (percent_bps >= 0 AND percent_bps <= 10000),\n  min_minor      bigint NOT NULL DEFAULT 0 CHECK (min_minor >= 0),\n  max_minor      bigint CHECK (max_minor IS NULL OR max_minor >= 0),\n  taxable        boolean NOT NULL DEFAULT false,\n  revenue_account text NOT NULL DEFAULT '4300',\n  active         boolean NOT NULL DEFAULT true,\n  updated_by     text,\n  updated_at     timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE dunning_rules (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  code           text NOT NULL UNIQUE,\n  name           text NOT NULL,\n  description    text NOT NULL DEFAULT '',\n  active         boolean NOT NULL DEFAULT true,\n  -- Whom it applies to. Every condition that is set must hold; the rule with the highest priority (then the most conditions) wins.\n  priority       integer NOT NULL DEFAULT 100,\n  market         char(2),                                                  -- the customer's market, or any\n  customer_kind  text NOT NULL DEFAULT 'ANY' CHECK (customer_kind IN ('ANY','INDIVIDUAL','BUSINESS')),\n  segments       text[] NOT NULL DEFAULT '{}',                             -- specific customer segments, or any\n  vip            text NOT NULL DEFAULT 'ANY' CHECK (vip IN ('ANY','YES','NO')),\n  credit_risk    text NOT NULL DEFAULT 'ANY' CHECK (credit_risk IN ('ANY','HIGH','NORMAL')),\n  partial        jsonb NOT NULL DEFAULT '{}',                              -- what a partial payment does: { thresholdPercent, action: RESET_TO_SOFT_BAR | PAUSE, pauseDays }\n  version        integer NOT NULL DEFAULT 1,\n  created_by     text NOT NULL DEFAULT 'system',\n  updated_by     text,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  updated_at     timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE dunning_rule_steps (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  rule_id        uuid NOT NULL REFERENCES dunning_rules (id) ON DELETE CASCADE,\n  position       integer NOT NULL,\n  name           text NOT NULL,\n  enabled        boolean NOT NULL DEFAULT true,\n  trigger_kind   text NOT NULL CHECK (trigger_kind IN ('DAYS_PAST_DUE','BALANCE')),\n  days           integer CHECK (days IS NULL OR days BETWEEN 0 AND 365),   -- D+X\n  balance_minor  bigint CHECK (balance_minor IS NULL OR balance_minor > 0),-- the overdue balance at or above which it applies\n  action         text NOT NULL CHECK (action IN ('NOTIFY','SOFT_BAR','HARD_BAR','LATE_FEE','TERMINATE','COLLECTIONS_TRANSFER','CASE_TASK')),\n  params         jsonb NOT NULL DEFAULT '{}',\n  exclusions     jsonb NOT NULL DEFAULT '{}',                              -- { dispute, vip, arrangement }\n  UNIQUE (rule_id, position)\n);\nCREATE INDEX dunning_rule_steps_rule_idx ON dunning_rule_steps (rule_id, position);\n\n-- A run is one account's walk down a ladder: which rule, a copy of its steps as they were at the start, and where it stands.\nALTER TABLE dunning_runs\n  ADD COLUMN rule_id        uuid,\n  ADD COLUMN rule_code      text,\n  ADD COLUMN rule_version   integer,\n  ADD COLUMN ladder         jsonb,\n  ADD COLUMN paused_until   date,\n  ADD COLUMN resets         integer NOT NULL DEFAULT 0;\n-- The log of what was done (or held back) at each step.\nALTER TABLE dunning_steps DROP CONSTRAINT IF EXISTS dunning_steps_run_id_step_key;\nALTER TABLE dunning_steps\n  ADD COLUMN step_key   text,\n  ADD COLUMN step_name  text,\n  ADD COLUMN status     text NOT NULL DEFAULT 'APPLIED' CHECK (status IN ('APPLIED','SUPERSEDED','HELD','FAILED','REVERSED')),\n  ADD COLUMN reason     text,\n  ADD COLUMN executed_at timestamptz NOT NULL DEFAULT now();\nUPDATE dunning_steps SET step_key = step WHERE step_key IS NULL;\nCREATE UNIQUE INDEX dunning_steps_run_key_uq ON dunning_steps (run_id, step_key);\nCREATE INDEX dunning_runs_account_idx ON dunning_runs (account_id, started_at DESC);\n\n-- A customer who has agreed a plan to pay what is owed in instalments is not chased while they keep to it.\nCREATE TABLE payment_arrangements (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  account_id    uuid NOT NULL,\n  customer_id   uuid NOT NULL,\n  status        text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','COMPLETED','BROKEN','CANCELLED')),\n  total_minor   bigint NOT NULL CHECK (total_minor > 0),\n  currency      char(3) NOT NULL,\n  installments  jsonb NOT NULL,                                            -- [{ dueDate, amountMinor }]\n  grace_days    integer NOT NULL DEFAULT 2,\n  reason        text NOT NULL DEFAULT '',\n  created_by    text NOT NULL,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  ended_at      timestamptz,\n  end_reason    text\n);\nCREATE INDEX payment_arrangements_account_idx ON payment_arrangements (account_id, created_at DESC);\nCREATE UNIQUE INDEX payment_arrangements_active_uq ON payment_arrangements (account_id) WHERE status = 'ACTIVE';\n\n-- Debt placed with an external collection agency, and the file it was sent in.\nCREATE TABLE collection_placements (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  account_id    uuid NOT NULL,\n  customer_id   uuid NOT NULL,\n  run_id        bigint,\n  balance_minor bigint NOT NULL,\n  currency      char(3) NOT NULL,\n  invoices      jsonb NOT NULL DEFAULT '[]',\n  written_off   boolean NOT NULL DEFAULT false,                            -- the receivable is out of the ledger; the agency may still recover it\n  reason        text NOT NULL DEFAULT 'NON_PAYMENT',\n  status        text NOT NULL DEFAULT 'PLACED' CHECK (status IN ('PLACED','RECOVERED','RECALLED')),\n  placed_at     timestamptz NOT NULL DEFAULT now(),\n  batch_id      text,\n  exported_at   timestamptz,\n  recovered_minor bigint NOT NULL DEFAULT 0\n);\nCREATE INDEX collection_placements_pending_idx ON collection_placements (placed_at) WHERE exported_at IS NULL AND status = 'PLACED';\nCREATE INDEX collection_placements_account_idx ON collection_placements (account_id, placed_at DESC);\n\n-- What an account manager is asked to do before the network is touched.\nINSERT INTO case_taxonomy (id, parent_id, level, name, sort_order, case_type, default_severity, needs_dispatch, skills, equipment) VALUES\n  ('billing.collections',          'billing',             2, 'Collections follow-up', 20, NULL, NULL, false, '{}', '{}'),\n  ('billing.collections.followup', 'billing.collections', 3, 'Overdue account follow-up', 10, 'GENERAL', 'MINOR_INQUIRY', false, '{}', '{}')\n  ON CONFLICT (id) DO NOTHING;\n\n-- A late fee is an invoice of its own; this says which dunning run charged it.\nALTER TABLE invoices ADD COLUMN IF NOT EXISTS late_fee_run_id bigint;\n" },
  { name: "0041_integration_hub.sql", sql: "-- Integration hub: the settings behind the northbound API gateway and every outside system Meridian talks to.\n--  * integration_endpoints: connection settings for the outside systems (WFM, network elements, SM-DP+, SAP, payment providers); secrets are encrypted by the application\n--  * oauth_clients: OAuth 2.0 client-credentials clients for the northbound APIs (only a hash of the secret is kept; a rotated secret stays valid for a grace period)\n--  * rate_limit_rules + rate_limit_buckets: sliding-window limits per channel\n--  * webhook_subscriptions: outbound partner webhooks, inbound verification keys, and TM Forum 688 subscriptions\n--  * event_topic_mappings: which internal event goes to which external topic\n--  * gateway_idempotency_keys: one result per (client, X-Idempotency-Key)\n--  * integration_audit_log: one row per northbound call\n\nCREATE TABLE integration_endpoints (\n  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  group_key      text NOT NULL CHECK (group_key IN ('gateway','webhooks','wfm','network','finance','events')),\n  kind           text NOT NULL,                       -- e.g. WFM_GATEWAY, NETWORK_ELEMENT, SMDP_PLUS, SAP_FICO, PAYMENT_GATEWAY\n  name           text NOT NULL,\n  url            text,\n  fallback_url   text,\n  timeout_ms     integer NOT NULL DEFAULT 10000 CHECK (timeout_ms BETWEEN 100 AND 120000),\n  config         jsonb NOT NULL DEFAULT '{}',         -- non-secret settings (protocol, pool size, slot rules, matching id parameters, ...)\n  secret_enc     text,                                -- encrypted credentials (client secret, password, certificate bundle, ...)\n  enabled        boolean NOT NULL DEFAULT true,\n  updated_by     text,\n  updated_at     timestamptz NOT NULL DEFAULT now(),\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (group_key, kind, name)\n);\n\nCREATE TABLE oauth_clients (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  client_id         text NOT NULL UNIQUE,\n  name              text NOT NULL,\n  channel           text NOT NULL DEFAULT 'DEFAULT',  -- decides the rate limit\n  scopes            text[] NOT NULL DEFAULT '{}',\n  token_ttl_seconds integer NOT NULL DEFAULT 900 CHECK (token_ttl_seconds BETWEEN 60 AND 86400),\n  secret_hash       text NOT NULL,\n  prev_secret_hash  text,                             -- the secret before the last rotation, valid until prev_expires_at\n  prev_expires_at   timestamptz,\n  rotated_at        timestamptz,\n  status            text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','REVOKED')),\n  created_by        text NOT NULL,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  last_used_at      timestamptz,\n  revoked_at        timestamptz\n);\n\n-- API keys (api_clients, migration 0005) gain a channel for rate limiting, an optional HMAC signing secret, and an expiry.\nALTER TABLE api_clients\n  ADD COLUMN channel text NOT NULL DEFAULT 'DEFAULT',\n  ADD COLUMN hmac_secret_enc text,\n  ADD COLUMN expires_at timestamptz;\n\nCREATE TABLE rate_limit_rules (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  channel     text NOT NULL UNIQUE,                   -- SELF_CARE, RETAIL_POS, PARTNER_PORTAL, ... or DEFAULT\n  per_minute  integer NOT NULL CHECK (per_minute BETWEEN 1 AND 100000),\n  enabled     boolean NOT NULL DEFAULT true,\n  updated_by  text,\n  updated_at  timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE rate_limit_buckets (\n  subject     text NOT NULL,                          -- the client the limit applies to\n  minute      bigint NOT NULL,                        -- unix minute\n  hits        integer NOT NULL DEFAULT 0,\n  PRIMARY KEY (subject, minute)\n);\n\nCREATE TABLE webhook_subscriptions (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  kind          text NOT NULL CHECK (kind IN ('OUTBOUND','INBOUND','TMF688')),\n  name          text NOT NULL,\n  target_url    text,                                 -- OUTBOUND / TMF688: where notifications go\n  auth_kind     text NOT NULL DEFAULT 'NONE' CHECK (auth_kind IN ('NONE','BEARER','HMAC')),\n  secret_enc    text,                                 -- bearer token, or the HMAC key (outbound signing, inbound verification)\n  provider      text,                                 -- INBOUND: which outside system calls us (payment gateway, courier, dealer channel)\n  events        text[] NOT NULL DEFAULT '{}',         -- event types; empty = all\n  query         text,                                 -- TMF688: the subscriber's filter (e.g. \"eventType=ServiceOrderStateChangeEvent\")\n  retry_max     integer NOT NULL DEFAULT 5 CHECK (retry_max BETWEEN 0 AND 20),\n  retry_backoff_seconds integer NOT NULL DEFAULT 30 CHECK (retry_backoff_seconds BETWEEN 1 AND 86400),\n  status        text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','PAUSED','FAILED')),\n  client_id     text,                                 -- the OAuth/API client that registered it (TMF688), if any\n  created_by    text NOT NULL,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_at    timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX webhook_subscriptions_kind_idx ON webhook_subscriptions (kind, status);\n\nCREATE TABLE event_topic_mappings (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  event_type  text NOT NULL,                          -- ORDER_CREATED, SIM_SWAPPED, SERVICE_SUSPENDED, ...\n  topic       text NOT NULL,                          -- the external topic (Kafka topic name)\n  enabled     boolean NOT NULL DEFAULT true,\n  updated_by  text,\n  updated_at  timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (event_type, topic)\n);\n\nCREATE TABLE gateway_idempotency_keys (\n  client_ref    text NOT NULL,\n  key           text NOT NULL,\n  request_hash  text NOT NULL,                        -- the same key with a different request is refused\n  status        text NOT NULL DEFAULT 'IN_PROGRESS' CHECK (status IN ('IN_PROGRESS','DONE')),\n  http_status   integer,\n  response      jsonb,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (client_ref, key)\n);\n\nCREATE TABLE integration_audit_log (\n  id           bigserial PRIMARY KEY,\n  at           timestamptz NOT NULL DEFAULT now(),\n  client_ref   text,\n  channel      text,\n  method       text NOT NULL,\n  path         text NOT NULL,\n  status       integer NOT NULL,\n  scope        text,\n  idempotency_key text,\n  ms           integer,\n  detail       jsonb\n);\nCREATE INDEX integration_audit_log_at_idx ON integration_audit_log (at DESC);\nCREATE INDEX integration_audit_log_client_idx ON integration_audit_log (client_ref, at DESC);\n" },
  { name: "0042_subscriber_operations.sql", sql: "-- Subscriber operations through the northbound API: one-time passwords for sensitive changes, plan changes scheduled for the next bill, and value-added\n-- services that hang off a mobile service.\n\nCREATE TABLE subscriber_otps (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  service_id   uuid NOT NULL,\n  purpose      text NOT NULL CHECK (purpose IN ('SIM_SWAP')),\n  code_hash    text NOT NULL,                       -- sha256 of service + code; the code itself is only in the SMS\n  attempts     integer NOT NULL DEFAULT 0,\n  expires_at   timestamptz NOT NULL,\n  consumed_at  timestamptz,\n  created_by   text NOT NULL,\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX subscriber_otps_service_idx ON subscriber_otps (service_id, created_at DESC);\n\nALTER TABLE services ADD COLUMN parent_service_id uuid;      -- a value-added service belongs to the mobile service it was added to\nALTER TABLE services ADD COLUMN sim_swapped_at timestamptz;  -- fraud screens look at recent swaps\nCREATE INDEX services_parent_idx ON services (parent_service_id) WHERE parent_service_id IS NOT NULL;\n\nCREATE TABLE pending_plan_changes (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  service_id   uuid NOT NULL,\n  account_id   uuid NOT NULL,\n  from_offer_id text NOT NULL,\n  offer_id     text NOT NULL,\n  effective_on date NOT NULL,                       -- the account's next bill date\n  add_ons      jsonb NOT NULL DEFAULT '[]',\n  status       text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPLIED','CANCELLED','FAILED')),\n  detail       jsonb NOT NULL DEFAULT '{}',\n  created_by   text NOT NULL,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  applied_at   timestamptz\n);\nCREATE UNIQUE INDEX pending_plan_changes_one_uq ON pending_plan_changes (service_id) WHERE status = 'PENDING';\nCREATE INDEX pending_plan_changes_due_idx ON pending_plan_changes (effective_on) WHERE status = 'PENDING';\n" },
];
